	'Serotonin-norepinephrine reuptake inhibitor': 'SNRI',
	'Monoamine oxidase inhibitor': 'MAOI',
	'Tetrahydrocannabinol': 'THC',
	'Lisdexamfetamine': 'Vyvanse',
	'5-Hydroxytryptophan': '5-HTP',
	'2-Fluorodeschloroketamine': '2F-DCK',
	'Deschloroketamine': 'DCK',
	'O-Desmethyltramadol': 'O-DSMT',
	'4-Methylmethcathinone': 'Mephedrone',
	'Psilocybin mushrooms': 'Mushrooms',
	'Peganum harmala': 'Syrian rue',
	'Banisteriopsis caapi': 'Caapi vine',
	'Anadenanthera peregrina': 'Yopo',
	'Hyoscyamus niger (botany)': 'Henbane',
	'Atropa belladonna': 'Belladonna',
	'Substituted phenethylamines': 'Phenethylamines',
	'Substituted amphetamines': 'Amphetamines',
