// ── Scrubbable area chart ─────────────────────────────────────────

type Pt = { x: number; y: number };
type Series = { key: string; label: string; sub?: string; points: Pt[]; color: string };
type Lane = { label: string; sub?: string; color?: string; height?: number; min: number; max: number; diverging?: boolean; linear?: boolean; marks?: number[]; series: Series[] };

// Monotone cubic (Fritsch–Carlson): smooth, but never overshoots the data.
function smoothPath(p: Pt[]) {
	if (p.length === 0) return '';
	if (p.length === 1) return `M${p[0].x},${p[0].y}`;
	const n = p.length;
	const d = p.slice(0, -1).map((a, i) => (p[i + 1].y - a.y) / (p[i + 1].x - a.x || 1e-9));
	const m = p.map((_, i) => (i === 0 ? d[0] : i === n - 1 ? d[n - 2] : d[i - 1] * d[i] <= 0 ? 0 : (d[i - 1] + d[i]) / 2));
	for (let i = 0; i < n - 1; i++) {
		if (d[i] === 0) {
			m[i] = 0;
			m[i + 1] = 0;
			continue;
		}
		const a = m[i] / d[i], b = m[i + 1] / d[i], s = a * a + b * b;
		if (s > 9) {
			const k = 3 / Math.sqrt(s);
			m[i] = k * a * d[i];
			m[i + 1] = k * b * d[i];
		}
	}
	let path = `M${p[0].x},${p[0].y}`;
	for (let i = 0; i < n - 1; i++) {
		const h = (p[i + 1].x - p[i].x) / 3;
		path += `C${p[i].x + h},${p[i].y + m[i] * h} ${p[i + 1].x - h},${p[i + 1].y - m[i + 1] * h} ${p[i + 1].x},${p[i + 1].y}`;
	}
	return path;
}
const interp = (pts: Pt[], x: number) => {
	if (!pts.length) return null;
	if (x <= pts[0].x) return pts[0].y;
	for (let i = 1; i < pts.length; i++)
		if (x <= pts[i].x) {
			const a = pts[i - 1], b = pts[i];
			return a.y + ((b.y - a.y) * (x - a.x)) / (b.x - a.x || 1e-9);
		}
	return pts[pts.length - 1].y;
};

function ScrubChart({
	id,
	lanes,
	xMax,
	x,
	onScrub,
	ticks = [],
	xLabels,
	laneHeight = 56,
	cursorLabel,
}: {
	id: string;
	lanes: Lane[];
	xMax: number;
	x: number;
	onScrub: (x: number) => void;
	ticks?: { x: number; on: boolean; active: boolean }[];
	markers?: { x: number; label: string }[];
	xLabels: { x: number; label: string }[];
	laneHeight?: number;
	cursorLabel?: string;
}) {
	const ref = useRef<HTMLDivElement | null>(null);
	const dragging = useRef(false);
	const [w, setW] = useState(320);
	useEffect(() => {
		const el = ref.current;
		if (!el) return;
		const ro = new ResizeObserver(([e]) => setW(Math.max(260, e.contentRect.width)));
		ro.observe(el);
		return () => ro.disconnect();
	}, []);
	const padX = 2, labelH = 20, gap = 14, axis = 28, pillH = cursorLabel ? 26 : 0;
	const heights = lanes.map((l) => l.height ?? laneHeight);
	const tops = heights.map((_, i) => heights.slice(0, i).reduce((a, b) => a + labelH + b + gap, 0) + labelH + pillH);
	const H = heights.reduce((a, b) => a + labelH + b + gap, 0) - gap + axis + pillH;
	const sx = (v: number) => padX + (clamp(v, 0, xMax) / xMax) * (w - 2 * padX);
	const sy = (lane: Lane, i: number, v: number) => tops[i] + (1 - (v - lane.min) / (lane.max - lane.min || 1)) * heights[i];
	const scrubAt = (clientX: number) => {
		const r = ref.current!.getBoundingClientRect();
		onScrub(clamp(((clientX - r.left - padX) / (w - 2 * padX)) * xMax, 0, xMax));
	};
	const cx = sx(x);
	const plotBottom = H - axis;
	const labelEvery = w < 480 ? Math.ceil(xLabels.length / 5) : w < 720 ? Math.ceil(xLabels.length / 8) : 1;
	const linePath = (p: Pt[]) => p.map((q, i) => `${i ? 'L' : 'M'}${q.x},${q.y}`).join('');

	return (
		<div ref={ref} style={{ width: '100%', minWidth: 0, overflow: 'hidden', userSelect: 'none' }}>
			<svg
				width={w}
				height={H}
				style={{ display: 'block', touchAction: 'pan-y', cursor: 'ew-resize', overflow: 'visible', userSelect: 'none', WebkitUserSelect: 'none' }}
				onPointerDown={(e) => {
					e.preventDefault();
					dragging.current = true;
					(e.currentTarget as SVGSVGElement).setPointerCapture(e.pointerId);
					scrubAt(e.clientX);
				}}
				onPointerMove={(e) => dragging.current && scrubAt(e.clientX)}
				onPointerUp={() => (dragging.current = false)}
				onPointerCancel={() => (dragging.current = false)}
				role="slider"
				aria-valuemin={0}
				aria-valuemax={xMax}
				aria-valuenow={x}
				tabIndex={0}
				onKeyDown={(e) => {
					if (e.key === 'ArrowRight') onScrub(clamp(x + xMax / 100, 0, xMax));
					if (e.key === 'ArrowLeft') onScrub(clamp(x - xMax / 100, 0, xMax));
				}}
			>
				<defs>
					{lanes.map((lane, li) =>
						lane.series.map((s) =>
							lane.diverging ? (
								<linearGradient key={s.key} id={`${id}-${li}-${s.key}`} gradientUnits="userSpaceOnUse" x1="0" y1={tops[li]} x2="0" y2={tops[li] + heights[li]}>
									<stop offset="0%" stopColor={C.mint} stopOpacity="0.5" />
									<stop offset="50%" stopColor={C.mint} stopOpacity="0.05" />
									<stop offset="50%" stopColor={C.coral} stopOpacity="0.05" />
									<stop offset="100%" stopColor={C.coral} stopOpacity="0.5" />
								</linearGradient>
							) : (
								<linearGradient key={s.key} id={`${id}-${li}-${s.key}`} x1="0" y1="0" x2="0" y2="1">
									<stop offset="0%" stopColor={s.color} stopOpacity="0.32" />
									<stop offset="100%" stopColor={s.color} stopOpacity="0" />
								</linearGradient>
							),
						),
					)}
				</defs>

				{lanes.map((lane, li) => {
					const base = lane.diverging ? sy(lane, li, 0) : tops[li] + heights[li];
					return (
						<g key={`${lane.label}-${li}`}>
							<text x={padX} y={tops[li] - 7} fontSize="12" fontWeight="600" fill={lane.color ?? C.text}>
								{lane.label}
								{lane.sub && (
									<tspan fill={C.faint} fontWeight="400" dx="8">
										{lane.sub}
									</tspan>
								)}
							</text>
							{lane.diverging && (
								<>
									<text x={w - padX} y={tops[li] - 7} fontSize="11" fill={C.faint} textAnchor="end">
										<tspan fill={C.mint}>good</tspan> / <tspan fill={C.coral}>rough</tspan>
									</text>
									<line x1={padX} x2={w - padX} y1={tops[li]} y2={tops[li]} stroke="rgba(255,255,255,.06)" />
									<line x1={padX} x2={w - padX} y1={tops[li] + heights[li]} y2={tops[li] + heights[li]} stroke="rgba(255,255,255,.06)" />
								</>
							)}
							<line x1={padX} x2={w - padX} y1={base} y2={base} stroke="rgba(255,255,255,.14)" />
							{lane.series.map((s) => {
								const pts = s.points.map((p) => ({ x: sx(p.x), y: sy(lane, li, clamp(p.y, lane.min, lane.max)) }));
								if (!pts.length) return null;
								// Linear lanes (mood) break where the data has gaps of more than 2 h, instead of drawing across them.
								const segs: Pt[][] = [];
								s.points.forEach((p, k) => {
									if (k === 0 || (lane.linear && p.x - s.points[k - 1].x > 2)) segs.push([]);
									segs[segs.length - 1].push(pts[k]);
								});
								const line = segs.map((g) => (lane.linear ? linePath(g) : smoothPath(g))).join('');
								const area = segs.map((g) => `${lane.linear ? linePath(g) : smoothPath(g)}L${g[g.length - 1].x},${base}L${g[0].x},${base}Z`).join('');
								return (
									<g key={s.key}>
										<path d={area} fill={`url(#${id}-${li}-${s.key})`} />
										<path d={line} fill="none" stroke={lane.diverging ? 'rgba(255,255,255,.85)' : s.color} strokeWidth="1.6" strokeLinejoin="round" />
										{lane.linear && pts.map((p, k) => <circle key={k} cx={p.x} cy={p.y} r={2.2} fill="#fff" opacity="0.85" />)}
									</g>
								);
							})}
							{(lane.marks ?? []).map((m, k) => (
								<circle key={`d${k}`} cx={sx(m)} cy={base} r={3.5} fill={lane.color ?? C.coral} stroke={C.deep} strokeWidth="1.5" />
							))}
							{lane.series.map((s) => {
								const inside = s.points.length && x >= s.points[0].x && x <= s.points[s.points.length - 1].x;
								const v = inside ? interp(s.points, x) : null;
								if (v == null) return null;
								return <circle key={`dot-${s.key}`} cx={cx} cy={sy(lane, li, clamp(v, lane.min, lane.max))} r={4} fill="#fff" />;
							})}
						</g>
					);
				})}

				{ticks.map((tk, i) => (
					<circle key={`tk${i}`} cx={sx(tk.x)} cy={plotBottom + 9} r={tk.active ? 4.5 : 3} fill={tk.on ? C.cyan : 'rgba(255,255,255,.35)'} stroke={tk.active ? '#fff' : 'none'} strokeWidth={1.5} />
				))}
				{xLabels.map((l, i) =>
					i % labelEvery === 0 ? (
						<text key={`xl${i}`} x={sx(l.x)} y={H - 2} fill={C.faint} fontSize="11" textAnchor={i === 0 ? 'start' : 'middle'}>
							{l.label}
						</text>
					) : null,
				)}
				<line x1={cx} x2={cx} y1={pillH ? 20 : 0} y2={plotBottom + 2} stroke="#fff" strokeOpacity="0.95" strokeWidth="2" />
				{cursorLabel && (
					<g transform={`translate(${clamp(cx, padX + 24, w - padX - 24)}, 10)`}>
						<rect x={-24} y={-10} width={48} height={20} rx={10} fill="#fff" />
						<text x={0} y={4} textAnchor="middle" fontSize="11.5" fontWeight="700" fill={C.deep} style={{ fontVariantNumeric: 'tabular-nums' }}>
							{cursorLabel}
						</text>
					</g>
				)}
			</svg>
		</div>
	);
}

type Mark = { t: number; method: string; raw: string; start: number; end: number; valence: number | null };
type Milestone = { label: string; t: number; at: number };

// Locate each time mark in the original text. Snippets were stored with whitespace collapsed, so search a
// collapsed copy of the body and map positions back. Then re-time the marks in reading order so the story only
// moves forward, repairing two upstream parsing errors:
//  - clock times were measured from the wrong anchor and sometimes the wrong half of the day ("12:15 pm" next
//    to "T+0:00" stored as T+12:15, "01:00" as T+21); the first clock time is pinned to the mark just before
//    it, later ones keep their spacing from it, choosing the ±12 h reading that follows on;
//  - "T+15:00" written as minutes:seconds was read as 15 hours; both readings are considered.
function locateMarks(body: string, marks: Record<string, unknown>[]): Mark[] {
	const norm: string[] = [];
	const map: number[] = [];
	let prevSpace = false;
	for (let i = 0; i < body.length; i++) {
		const ch = body[i];
		if (/\s/.test(ch)) {
			if (prevSpace) continue;
			norm.push(' ');
			prevSpace = true;
		} else {
			norm.push(ch);
			prevSpace = false;
		}
		map.push(i);
	}
	const nb = norm.join('');
	const found: Mark[] = [];
	for (const m of marks) {
		const raw = S(m.raw).replace(/\s+/g, ' ').trim();
		if (!raw) continue;
		const snip = S(m.snippet).replace(/\s+/g, ' ').trim();
		let at = -1;
		if (snip) {
			const s = nb.indexOf(snip);
			const r = s >= 0 ? snip.indexOf(raw) : -1;
			if (r >= 0) at = s + r;
		}
		if (at < 0) {
			// Next unused occurrence of the raw text.
			let from = 0;
			while ((at = nb.indexOf(raw, from)) >= 0 && found.some((f) => f.start === map[at])) from = at + 1;
		}
		if (at < 0) continue;
		found.push({ t: N(m.t), method: S(m.method), raw, start: map[at], end: map[at + raw.length - 1] + 1, valence: m.valence == null ? null : N(m.valence) });
	}
	for (const lm of body.matchAll(/(^|\n)[ \t]*(?:T\s*\+\s*)?(\d{1,3}[:.]\d{2})(?![:.]?\d)/g)) {
		const start = (lm.index ?? 0) + lm[0].length - lm[2].length;
		if (found.some((f) => start < f.end && start + lm[2].length > f.start)) continue;
		const [h, mm] = lm[2].split(/[:.]/).map(Number);
		if (mm >= 60) continue;
		found.push({ t: h + mm / 60, method: 'narrative_tplus', raw: lm[2], start, end: start + lm[2].length, valence: null });
	}
	const ordered = found.sort((a, b) => a.start - b.start || a.t - b.t);
	const clean: Mark[] = [];
	const aside = (m: Mark) => m.method === 'relative' && /\b(day|days|tomorrow|morning|night|evening|week|weeks|month|months|year|years)\b/i.test(m.raw);
	for (const m of ordered) if (!aside(m) && (!clean.length || m.start >= clean[clean.length - 1].end)) clean.push(m);

	const mmss = /\b(min(?:ute)?s?\s*[:/]\s*sec(?:ond)?s?|mm:ss)\b/i.test(body);
	let prev: number | null = null;
	let anchor: { stored: number; t: number } | null = null;
	for (const m of clean) {
		let options: number[];
		const before = body.slice(Math.max(0, m.start - 6), m.start);
		const hm = m.raw.match(/^(\d{1,3})[:.](\d{2})$/);
		if (hm && mmss) {
			const v = Number(hm[1]) + Number(hm[2]) / 60;
			options = [v / 60, v]; // minutes:seconds, until the story passes an hour and switches to hours:minutes
		} else if (hm && /T\s*\+\s*$/i.test(before)) {
			const v = Number(hm[1]) + Number(hm[2]) / 60;
			const hms = /^[:.]\d{2}/.test(body.slice(m.end, m.end + 3));
			const leap = prev != null && v - prev > 4 && v / 60 >= prev - 0.25;
			options = hms || !leap ? [v] : [v / 60];
		} else if (m.method === 'clock_time') {
			if (!anchor) {
				const t0 = prev != null && Math.abs(m.t - prev) > 1 ? prev : m.t;
				anchor = { stored: m.t, t: t0 };
				options = [t0];
			} else {
				const base = anchor.t + (m.t - anchor.stored);
				options = [base, base - 12, base + 12, base - 24, base + 24];
			}
		} else {
			options = [m.t];
			const hm = m.raw.match(/(\d{1,2})[:.](\d{2})(?![:.]\d)/);
			if (m.method === 'narrative_tplus' && hm) {
				const v = Number(hm[1]) + Number(hm[2]) / 60;
				options = prev != null && v - prev > 4 && v / 60 >= prev - 0.25 ? [v / 60] : [v];
			}
		}
		options = options.filter((c) => c >= 0);
		const after = prev == null ? options : options.filter((c) => c >= prev! - 0.25);
		const pool = after.length ? after : options;
		if (pool.length) {
			const ref = prev ?? 0;
			m.t = pool.reduce((a, b) => (Math.abs(a - ref) <= Math.abs(b - ref) ? a : b));
		}
		prev = m.t;
	}
	return clean.filter((m) => m.t >= 0);
}

// A close reading quotes the story at each moment and gives its time. Find each quote in the text and pin the
// mark there: on the time as written just before it when there is one, otherwise as a time stamp added in front
// of the quote (an empty range). These times are more reliable than the automatic marks.
function locateObs(body: string, obs: Record<string, unknown>[]): Mark[] {
	const fold = (s: string) => s.toLowerCase().replace(/[‘’`�]/g, "'").replace(/[“”]/g, '"');
	const fb = fold(body);
	const norm: string[] = [];
	const map: number[] = [];
	let prevSpace = false;
	for (let i = 0; i < fb.length; i++) {
		const sp = /\s/.test(fb[i]);
		if (sp && prevSpace) continue;
		norm.push(sp ? ' ' : fb[i]);
		prevSpace = sp;
		map.push(i);
	}
	map.push(body.length);
	const nb = norm.join('');
	const frags = (s: string) =>
		fold(s)
			.split(/\s*(?:\.\.\.|…|"\s*[;,:-]?\s*")\s*/)
			.map((f) => f.replace(/^[\s"'(]+|[\s"')]+$/g, '').replace(/\s+/g, ' '))
			.filter((f) => f.split(' ').length >= 3);
	const out: Mark[] = [];
	let from = 0;
	for (const o of [...obs].sort((a, b) => N(a.hrs) - N(b.hrs))) {
		let at = -1;
		search: for (const f of frags(S(o.description))) {
			const ws = f.split(' ');
			for (const n of [7, 5, 4, 3]) {
				if (ws.length < n) continue;
				const key = ws.slice(0, n).join(' ');
				at = nb.indexOf(key, from);
				if (at < 0) at = nb.indexOf(key);
				if (at >= 0) break search;
			}
		}
		if (at < 0) continue;
		let s = at, e = at;
		const orig = fold(S(o.time_original)).replace(/\s+/g, ' ').trim();
		if (orig && orig.length <= 24 && /\d/.test(orig)) {
			const k = nb.lastIndexOf(orig, at);
			if (k >= 0 && at - k <= 300) [s, e] = [k, k + orig.length];
		}
		const start = map[s], end = e > s ? map[e - 1] + 1 : start;
		out.push({ t: N(o.hrs), method: 'obs', raw: S(o.obs_index), start, end, valence: (MOMENT[S(o.sentiment)] ?? MOMENT.neutral).y });
		from = at + 1;
	}
	const clean: Mark[] = [];
	for (const m of out.sort((a, b) => a.start - b.start)) {
		const last = clean[clean.length - 1];
		if (!last || m.start >= last.end + (last.end === last.start ? 1 : 0)) clean.push(m);
	}
	return clean;
}

// Expected effect curve for one dose: nothing → first effects → peak → tapering off, using typical times from
// other closely read reports (route-specific when there are enough). Overlapping doses of a substance add up.
type Dose = { sub: string; amount: string; route: string; t: number; assumed: boolean };
const normRoute = (r: string) =>
	({ inhaled: 'smoked', vaporized: 'smoked', vaped: 'smoked', iv: 'injected', intravenous: 'injected', im: 'injected', snorted: 'insufflated' } as Record<string, string>)[r.toLowerCase()] ??
	r.toLowerCase();
function expectedCurves(doses: Dose[], timing: Record<string, unknown>[]) {
	const pick = (sub: string, route: string) =>
		timing.find((r) => S(r.sub) === sub && S(r.route) === normRoute(route)) ?? timing.find((r) => S(r.sub) === sub && S(r.route) === '*');
	const shape = (t0: number, r: Record<string, unknown>) => {
		const on = Math.max(0.01, N(r.on_m));
		const pk = Math.max(on + 0.02, N(r.pk_m));
		const pkHi = Math.max(pk + 0.05, N(r.pk_hi));
		const end = Math.max(pkHi + 0.1, N(r.end_m));
		const endHi = Math.max(end + 0.1, N(r.end_hi));
		return [
			{ x: t0, y: 0 },
			{ x: t0 + on, y: 0.15 },
			{ x: t0 + pk, y: 1 },
			{ x: t0 + pkHi, y: 0.85 },
			{ x: t0 + end, y: 0.3 },
			{ x: t0 + endHi, y: 0 },
		];
	};
	const at = (pts: Pt[], x: number) => (x <= pts[0].x || x >= pts[pts.length - 1].x ? 0 : (interp(pts, x) as number));
	const bySub = new Map<string, { curves: Pt[][]; n: number; peak: number }>();
	const missing = new Set<string>();
	for (const d of doses) {
		const r = pick(d.sub, d.route);
		if (!r) {
			missing.add(d.sub);
			continue;
		}
		const e = bySub.get(d.sub) ?? { curves: [], n: N(r.n), peak: N(r.pk_m) };
		e.curves.push(shape(d.t, r));
		bySub.set(d.sub, e);
	}
	let end = 0;
	const series: Series[] = [...bySub.entries()].map(([sub, e], i) => {
		const lo = Math.min(...e.curves.map((c) => c[0].x));
		const hi = Math.max(...e.curves.map((c) => c[c.length - 1].x));
		end = Math.max(end, hi);
		const xs = new Set<number>();
		for (const c of e.curves) for (const p of c) xs.add(p.x);
		for (let k = 0; k <= 120; k++) xs.add(lo + ((hi - lo) * k) / 120);
		const points = [...xs].sort((a, b) => a - b).map((x) => ({ x, y: e.curves.reduce((sum, c) => sum + at(c, x), 0) }));
		return { key: `exp${i}`, label: sub, sub: `peaks ~${fmtDur(e.peak)}`, color: SERIES[i % SERIES.length], points };
	});
	for (const s of series) missing.delete(s.label);
	return { series, missing: [...missing], end };
}

const HOUR_MS_AT_1X = 10_000; // one trip-hour plays in 10 s at 1×
const DWELL_MS = 1500; // pause on each mark while playing

// ── Highlighter ───────────────────────────────────────────────────
// Links what a moment says to the report text: the passage for the current moment gets a soft yellow wash, and
// words matching the moment's effects are highlighted in the effect's tone (green good, coral rough, yellow neutral).

const HI: Record<string, string> = { positive: 'rgba(166,242,228,.42)', negative: 'rgba(255,163,182,.45)', neutral: 'rgba(255,224,130,.42)' };
const PASSAGE_BG = 'rgba(255,224,130,.13)';
const STOP = new Set(['enhancement', 'suppression', 'alteration', 'alterations', 'effects', 'effect', 'increased', 'decreased', 'intensification',
	'distortion', 'distortions', 'sense', 'loss', 'changes', 'change', 'feelings', 'feeling', 'perception', 'physical', 'cognitive',
	'visual', 'auditory', 'tactile', 'motor', 'control', 'with', 'impending', 'appreciation', 'analysis', 'affection']);
type HiRule = { stem: string; effect: string; tone: string };
const rulesFor = (effects: string[], toneOf: (e: string) => string): HiRule[] => {
	const seen = new Set<string>();
	const out: HiRule[] = [];
	for (const effect of effects)
		for (const w of effect.toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/)) {
			if (w.length < 4 || STOP.has(w)) continue;
			const stem = w.length >= 8 ? w.slice(0, 5) : w.slice(0, 4);
			if (seen.has(stem)) continue;
			seen.add(stem);
			out.push({ stem, effect, tone: toneOf(effect) });
		}
	return out;
};
function markWords(text: string, rules: HiRule[], hover: string | null, key: string): (string | JSX.Element)[] {
	if (!rules.length || !text) return [text];
	const re = new RegExp(`\\b(${rules.map((r) => r.stem).join('|')})[a-z’']*`, 'gi');
	const out: (string | JSX.Element)[] = [];
	let last = 0;
	for (const m of text.matchAll(re)) {
		const r = rules.find((x) => x.stem === m[1].toLowerCase());
		if (!r || m.index == null) continue;
		if (m.index > last) out.push(text.slice(last, m.index));
		out.push(
			<mark key={`${key}-${m.index}`} title={r.effect} style={{ background: HI[r.tone], color: 'inherit', borderRadius: 4, padding: '0 2px', boxShadow: hover === r.effect ? '0 0 0 1.5px #fff' : 'none', transition: 'box-shadow .2s' }}>
				{m[0]}
			</mark>,
		);
		last = m.index + m[0].length;
	}
	if (last < text.length) out.push(text.slice(last));
	return out;
}

