// ── Tags & detail panel ───────────────────────────────────────────

type Open = { kind: 'effect' | 'substance'; name: string } | null;
const OpenCtx = createContext<{ open: (o: Open) => void; effectInfo: Map<string, EffectInfo>; classOf: (s: string) => string | undefined }>({ open: () => {}, effectInfo: new Map(), classOf: () => undefined });

function EffectTag({ name }: { name: string }) {
	const { open, effectInfo } = useContext(OpenCtx);
	return (
		<button className="rd-tag" onClick={() => open({ kind: 'effect', name })}>
			<span className="rd-dot" style={{ background: TONE_DOT[effectTone(effectInfo.get(name.toLowerCase()))] }} />
			{name}
		</button>
	);
}
function SubstanceTag({ name, note }: { name: string; note?: string }) {
	const { open, classOf } = useContext(OpenCtx);
	return (
		<button className="rd-tag" onClick={() => open({ kind: 'substance', name })} title={[name, classOf(name)].filter(Boolean).join(' · ')}>
			<ClassIcon cls={classOf(name)} size={15} color={C.coral} />
			{short(name)}
			{note && <span style={{ color: C.faint, fontWeight: 500 }}>{note}</span>}
		</button>
	);
}

function DetailPanel({ item, onClose, effectQ, subQ, timingQ, onReplay }: { item: Open; onClose: () => void; effectQ: Q; subQ: Q; timingQ: Q; onReplay: (s: string) => void }) {
	useEffect(() => {
		const k = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
		window.addEventListener('keydown', k);
		return () => window.removeEventListener('keydown', k);
	}, [onClose]);
	if (!item) return null;
	const q = item.kind === 'effect' ? effectQ : subQ;
	const r = rows(q)[0];
	return (
		<>
			<div className="rd-scrim" onClick={onClose} />
			<aside className="rd-sheet p-6" role="dialog" aria-label={item.name}>
				<div className="flex items-start justify-between gap-3">
					<div>
						<div className="rd-label">{item.kind === 'effect' ? 'Effect' : 'Substance'}</div>
						<h2 className="mt-1 text-3xl font-semibold" style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{item.kind === 'substance' ? short(item.name) : item.name}</h2>
						{item.kind === 'substance' && short(item.name) !== item.name && <div className="mt-1 text-sm" style={{ color: C.faint }}>{item.name}</div>}
					</div>
					<button onClick={onClose} className="rd-btn" aria-label="Close" style={{ padding: 8 }}>
						<X size={18} />
					</button>
				</div>
				{q.isLoading ? (
					<div className="rd-card mt-6 animate-pulse" style={{ height: 180 }} />
				) : !r ? (
					<p className="mt-6" style={{ color: C.soft }}>
						Nothing more on this yet.
					</p>
				) : item.kind === 'effect' ? (
					<div className="rd-in mt-5 grid gap-6">
						{S(r.category) && <div className="text-sm" style={{ color: C.faint }}>{S(r.category)}</div>}
						{S(r.description) && (
							<p style={{ fontFamily: SERIF, fontSize: 19, lineHeight: 1.55 }}>{sentences(S(r.description).replace(/,(\S)/g, ', $1'), 1)}</p>
						)}
						<div className="grid grid-cols-3 gap-3">
							{[
								['Reports', N(r.n_reports).toLocaleString(), C.text],
								['Felt good', `${Math.round(100 * N(r.pos))}%`, C.mint],
								['Felt rough', `${Math.round(100 * N(r.neg))}%`, C.coral],
							].map(([l, v, c]) => (
								<div key={l as string} className="rd-card p-3">
									<div className="text-2xl font-light" style={{ color: c as string }}>{v}</div>
									<div className="rd-label mt-1">{l}</div>
								</div>
							))}
						</div>
						{L(r.sub_names).length > 0 && (
							<div>
								<div className="rd-label mb-2">Most often with</div>
								<div className="flex flex-wrap gap-2">
									{L(r.sub_names).map((name, i) => (
										<SubstanceTag key={name} name={name} note={`${L(r.sub_counts)[i]} reports`} />
									))}
								</div>
							</div>
						)}
						<Sources className="" list={[S(r.url) ? [/psychonautwiki/i.test(S(r.url)) ? 'pw' : 'sei', S(r.url)] : 'sei', 'erowid']} />
					</div>
				) : (
					<div className="rd-in mt-5 grid gap-6">
						{(() => {
							const { desc, warning, aka } = describeSubstance(item.name, r, rows(timingQ));
							return (
								<>
									{desc && <p style={{ fontFamily: SERIF, fontSize: 19, lineHeight: 1.55 }}>{desc}</p>}
									{aka.length > 0 && (
										<div className="text-sm" style={{ color: C.soft }}>
											<span className="rd-label mr-2">Also known as</span>
											{aka.join(', ')}
										</div>
									)}
									{warning && (
										<div className="flex items-start gap-2 rounded-2xl p-3 text-sm" style={{ background: 'rgba(255,163,182,.12)', border: '1px solid rgba(255,163,182,.4)', color: C.text }}>
											<AlertTriangle size={16} color={C.coral} style={{ flexShrink: 0, marginTop: 2 }} />
											<span>{warning}</span>
										</div>
									)}
								</>
							);
						})()}
						{(() => {
							const t = rows(timingQ).find((x) => S(x.sub) === item.name && S(x.route) === '*');
							return t ? (
								<div className="grid grid-cols-3 gap-3">
									{[
										['First effects', N(t.on_m)],
										['Strongest', N(t.pk_m)],
										['Last effects', N(t.end_m)],
									].map(([l, v]) => (
										<div key={l as string} className="rd-card p-3">
											<div className="text-2xl font-light">{fmtDur(v as number)}</div>
											<div className="rd-label mt-1">{l}</div>
										</div>
									))}
								</div>
							) : null;
						})()}
						{L(r.effects).length > 0 && (
							<div>
								<div className="rd-label mb-2">Most reported effects</div>
								<div className="flex flex-wrap gap-2">
									{L(r.effects).map((e) => (
										<EffectTag key={e} name={e} />
									))}
								</div>
							</div>
						)}
						{(S(r.tolerance_full) || S(r.addiction) || L(r.cross_tol).length > 0) && (
							<div className="grid gap-2 text-sm" style={{ color: C.soft }}>
								{S(r.tolerance_full) && (
									<div>
										<span className="rd-label mr-2">Tolerance</span>
										builds {S(r.tolerance_full).replace(/^with\s+/i, '')}
										{S(r.tolerance_zero) ? `, back to baseline ${S(r.tolerance_zero).replace(/^after\s+/i, 'after ').replace(/^(?=\d)/, 'after ')}` : ''}
									</div>
								)}
								{S(r.addiction) && (
									<div>
										<span className="rd-label mr-2">Habit-forming</span>
										{S(r.addiction)}
									</div>
								)}
								{L(r.cross_tol).length > 0 && <CrossTol name={item.name} />}
							</div>
						)}
						<div className="text-sm" style={{ color: C.faint }}>
							{N(r.n_reports).toLocaleString()} reports · {N(r.n_read)} read closely
							<Sources className="mt-3" list={[S(r.url) ? ['pw', S(r.url)] : 'pw', 'erowid']} />
						</div>
						<button className="rd-btn" style={{ background: '#fff', color: C.deep, justifySelf: 'start' }} onClick={() => onReplay(item.name)}>
							Open full page
						</button>
					</div>
				)}
			</aside>
		</>
	);
}

function SubstanceIcon({ name }: { name: string }) {
	const { classOf } = useContext(OpenCtx);
	return <ClassIcon cls={classOf(name)} size={20} color={C.coral} />;
}

function DoseChip({ d, latest, count = 1 }: { d: { sub: string; amount: string; route: string; t: number; assumed: boolean }; latest: boolean; count?: number }) {
	const { open, classOf } = useContext(OpenCtx);
	return (
		<button className={`rd-tag rd-in shrink-0 ${latest ? 'rd-new' : ''}`} onClick={() => open({ kind: 'substance', name: d.sub })} title={[d.sub, classOf(d.sub)].filter(Boolean).join(' · ')}>
			<ClassIcon cls={classOf(d.sub)} size={15} color={C.coral} />
			{short(d.sub)}
			{d.route && <RouteIcon route={d.route} size={13} />}
			{count > 1 ? <span style={{ color: C.soft, fontWeight: 500 }}>×{count}</span> : /\d/.test(d.amount) && <span style={{ color: C.soft, fontWeight: 500 }}>{d.amount}</span>}
			<span className="tabular-nums" style={{ color: C.faint, fontWeight: 500 }}>{d.assumed ? '' : `${count > 1 ? 'last ' : ''}${fmtT(d.t)}`}</span>
		</button>
	);
}

// ── Browse: effects ───────────────────────────────────────────────

function EffectsBrowse({ q }: { q: Q }) {
	const searchRef = useRef<HTMLInputElement | null>(null);
	useFindKey(searchRef);
	const [filter, setFilter] = useState('');
	const groups = useMemo(() => {
		const g = new Map<string, { name: string; n: number }[]>();
		for (const r of rows(q)) {
			if (filter && !S(r.name).toLowerCase().includes(filter.toLowerCase())) continue;
			const c = S(r.category).replace(' Effects', '') || 'Other';
			if (!g.has(c)) g.set(c, []);
			g.get(c)!.push({ name: S(r.name), n: N(r.n) });
		}
		return [...g.entries()].sort((a, b) => b[1].length - a[1].length);
	}, [q.data, filter]);
	return (
		<section className="rd-in">
			<h1 className="text-4xl font-semibold">Effects</h1>
			<p className="mt-2" style={{ color: C.soft }}>
				Everything people described, grouped by type. Tap one to learn what it is.
			</p>
			<Sources className="mt-3" list={['sei', 'erowid']} />
			<input ref={searchRef} value={filter} onChange={(e) => setFilter(e.target.value)} placeholder="Search effects" className="rd-card mt-6 w-full px-5 py-3 text-base" style={{ borderRadius: 999, color: C.text, outline: 'none' }} />
			{q.isLoading ? (
				<div className="rd-card mt-6 animate-pulse" style={{ height: 240 }} />
			) : (
				<div className="mt-8 grid gap-8">
					{groups.map(([cat, list]) => (
						<div key={cat}>
							<div className="rd-label mb-3">
								{cat} · {list.length}
							</div>
							<div className="flex flex-wrap gap-2">
								{list.map((e) => (
									<EffectTag key={e.name} name={e.name} />
								))}
							</div>
						</div>
					))}
				</div>
			)}
			<Err q={q} />
		</section>
	);
}

// ── Browse: substances ────────────────────────────────────────────

// Top combinations for one substance, with how they went and any interaction note.
const focusCombosSQL = (sub: string) => `
WITH co AS (
  SELECT d2.canonical_substance AS s, count(DISTINCT d1.report_id) AS n
  FROM ${DB}."report_doses" d1 JOIN ${DB}."report_doses" d2 USING (report_id)
  WHERE d1.canonical_substance = '${esc(sub)}' AND d2.canonical_substance IS NOT NULL AND d2.canonical_substance <> '${esc(sub)}'
  GROUP BY 1 ORDER BY n DESC, 1 LIMIT 8
),
pairrep AS (
  SELECT DISTINCT d2.canonical_substance AS s, d1.report_id
  FROM ${DB}."report_doses" d1 JOIN ${DB}."report_doses" d2 USING (report_id)
  WHERE d1.canonical_substance = '${esc(sub)}' AND d2.canonical_substance IN (SELECT s FROM co)
),
val AS (
  SELECT report_id, avg(valence) AS v FROM ${DB}."timeline_sentiment"
  WHERE report_id IN (SELECT report_id FROM pairrep) GROUP BY 1
),
${pairSevCTEs(`SELECT '${esc(sub)}' AS a, s AS b FROM co`)},
stats AS (
  SELECT p.s, count(e.report_id) AS n_llm,
    avg((e.overall_sentiment = 'positive')::INT) AS pos, avg((e.overall_sentiment = 'negative')::INT) AS neg,
    avg(val.v) AS v
  FROM pairrep p LEFT JOIN ${DB}."llm_extractions" e USING (report_id) LEFT JOIN val USING (report_id)
  GROUP BY 1
)
SELECT co.s, co.n, stats.n_llm, stats.pos, stats.neg, stats.v, ps.sev, ps.status, ps.note
FROM co LEFT JOIN stats USING (s) LEFT JOIN pairsev ps ON ps.b = co.s
ORDER BY co.n DESC, co.s`;

// How reports with only this substance went.
const aloneSQL = (sub: string) => `
WITH rs AS (
  SELECT report_id, list(DISTINCT canonical_substance) AS subs
  FROM ${DB}."report_doses" WHERE canonical_substance IS NOT NULL GROUP BY 1
),
alone AS (SELECT report_id FROM rs WHERE len(subs) = 1 AND subs[1] = '${esc(sub)}')
SELECT count(*) AS n, count(e.report_id) AS n_llm,
  avg((e.overall_sentiment = 'positive')::INT) AS pos, avg((e.overall_sentiment = 'negative')::INT) AS neg
FROM alone LEFT JOIN ${DB}."llm_extractions" e USING (report_id)`;

function OutcomeBar({ pos, neg, n }: { pos: unknown; neg: unknown; n: number }) {
	if (n < 3) return <span className="text-xs" style={{ color: C.faint }}>too few close reads</span>;
	return (
		<span className="flex items-center gap-2" style={{ minWidth: 0 }}>
			<span className="flex overflow-hidden rounded-full" style={{ width: 90, height: 6, background: 'rgba(255,255,255,.08)', flexShrink: 0 }}>
				<span style={{ width: `${Math.round(100 * N(pos))}%`, background: C.mint }} />
				<span style={{ flex: 1 }} />
				<span style={{ width: `${Math.round(100 * N(neg))}%`, background: C.coral }} />
			</span>
			<span className="text-xs tabular-nums" style={{ color: C.soft, whiteSpace: 'nowrap' }}>
				<span style={{ color: C.mint }}>{Math.round(100 * N(pos))}%</span> good · <span style={{ color: C.coral }}>{Math.round(100 * N(neg))}%</span> rough
			</span>
		</span>
	);
}

// What people most often took it with, whether the mix carries a warning, and how it went.
function CombosList({ name, onCombo }: { name: string; onCombo: (a: string, b: string) => void }) {
	const { classOf } = useContext(OpenCtx);
	const combosQ = useSQLQuery(focusCombosSQL(name));
	const SEV: Record<number, { w: string; c: string }> = { 3: { w: 'dangerous', c: C.coral }, 2: { w: 'unsafe', c: C.amber }, 1: { w: 'caution', c: C.lav } };
	return (
		<>
			<span className="rd-label">Most often combined with</span>
			{combosQ.isLoading ? (
				<div className="mt-3 animate-pulse" style={{ height: 180 }} />
			) : rows(combosQ).length === 0 ? (
				<p className="mt-2 text-sm" style={{ color: C.faint }}>No combinations on record.</p>
			) : (
				<div className="mt-2 grid">
					{rows(combosQ).map((r) => {
						const other = S(r.s);
						const sev = SEV[N(r.sev)];
						return (
							<button
								key={other}
								onClick={() => onCombo(name, other)}
								className="rd-hover grid items-center rounded-xl px-2 py-3 text-left"
								style={{ gridTemplateColumns: 'minmax(0, 1fr) auto 16px', columnGap: 12, rowGap: 6, borderTop: `1px solid ${C.line}` }}
							>
								<span className="flex items-center gap-2 font-semibold" style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }} title={other}>
									<ClassIcon cls={classOf(other)} size={16} color={C.coral} />
									{short(other)}
								</span>
								<span className="text-xs font-semibold" style={{ color: sev?.c ?? C.faint, whiteSpace: 'nowrap' }}>
									{sev ? (
										<span className="inline-flex items-center gap-1" title={S(r.note)}>
											<AlertTriangle size={12} /> {sev.w}
										</span>
									) : r.status ? (
										<span style={{ color: C.mint }} title={S(r.note)}>low risk</span>
									) : (
										'no note'
									)}
								</span>
								<ChevronRight size={14} color={C.faint} style={{ gridRow: '1 / 3', gridColumn: 3 }} />
								<span className="flex flex-wrap items-center gap-x-3 gap-y-1" style={{ gridColumn: '1 / 3' }}>
									<span className="text-xs" style={{ color: C.faint, whiteSpace: 'nowrap' }}>{N(r.n)} reports together</span>
									<OutcomeBar pos={r.pos} neg={r.neg} n={N(r.n_llm)} />
								</span>
							</button>
						);
					})}
				</div>
			)}
			<p className="mt-3 text-xs" style={{ color: C.faint }}>
				Good / rough from closely read reports. “No note” isn’t the same as safe.
				<span className="ml-2 inline-block align-middle">
					<TripSitBadge />
				</span>
			</p>
		</>
	);
}

function FocusPanel({ name, onPick, onCombo, onClose }: { name: string; onPick: (s: string) => void; onCombo: (a: string, b: string) => void; onClose: () => void }) {
	const { open, classOf } = useContext(OpenCtx);
	const aloneQ = useSQLQuery(aloneSQL(name));
	const timingQ = useSQLQuery(timingSQL([name]));
	const t = rows(timingQ).find((r) => S(r.route) === '*');
	const al = rows(aloneQ)[0];
	return (
		<div className="rd-card rd-in mt-6 p-5 sm:p-6" onClick={(e) => e.stopPropagation()}>
			<div className="flex flex-wrap items-center justify-between gap-3">
				<h2 className="flex items-center gap-3 text-2xl font-semibold" style={{ whiteSpace: 'nowrap' }}>
					<ClassIcon cls={classOf(name)} size={22} color={C.coral} />
					{short(name)}
				</h2>
				<div className="flex items-center gap-2">
					<button className="rd-btn" style={{ background: '#fff', color: C.deep, padding: '5px 12px', fontSize: 13 }} onClick={() => onPick(name)}>
						Open page
					</button>
					<button className="rd-btn" aria-label="Close" style={{ padding: 7 }} onClick={onClose}>
						<X size={14} />
					</button>
				</div>
			</div>

			<div className="mt-4 grid gap-1 text-sm" style={{ color: C.soft }}>
				<span className="rd-label">On its own</span>
				{timingQ.isLoading || aloneQ.isLoading ? (
					<div className="animate-pulse" style={{ height: 20 }} />
				) : (
					<div className="flex flex-wrap items-center gap-x-5 gap-y-2">
						<span style={{ fontFamily: SERIF, fontSize: 17, color: C.text }}>
							{t ? `Kicks in ~${fmtDur(N(t.on_m))}, strongest ~${fmtDur(N(t.pk_m))}, fades by ~${fmtDur(N(t.end_m))}.` : 'Not enough close reads to time it.'}
						</span>
						{al && <OutcomeBar pos={al.pos} neg={al.neg} n={N(al.n_llm)} />}
					</div>
				)}
			</div>

			<div className="mt-6">
				<CombosList name={name} onCombo={onCombo} />
			</div>
		</div>
	);
}

function SubstancesBrowse({ q, onPick, onCombo }: { q: Q; onPick: (s: string) => void; onCombo: (a: string, b: string) => void }) {
	const [filter, setFilter] = useState('');
	const [focus, setFocusState] = useState<string | null>(null);
	const setFocus = (f: string | null) => {
		setFocusState(f);
		if (f) window.scrollTo({ top: 0, behavior: 'smooth' });
	};
	const { open, classOf } = useContext(OpenCtx);
	const coQ = useSQLQuery(coSQL(focus ?? ''), { enabled: !!focus });
	const co = new Map(rows(coQ).map((r) => [S(r.s), N(r.n)]));
	const list = rows(q).filter((r) => S(r.s).toLowerCase().includes(filter.trim().toLowerCase()));
	const searchRef = useRef<HTMLInputElement | null>(null);
	useFindKey(searchRef);
	useEffect(() => {
		const k = (e: KeyboardEvent) => e.key === 'Escape' && setFocus(null);
		window.addEventListener('keydown', k);
		return () => window.removeEventListener('keydown', k);
	}, []);

	return (
		<section className="rd-in" onClick={() => setFocus(null)} style={{ minHeight: '60vh' }}>
			<h1 className="text-4xl font-semibold">Substances</h1>
			<p className="mt-2" style={{ color: C.soft }}>
				{focus ? (
					<>
						Showing what people combined with <b style={{ color: C.text }}>{short(focus)}</b>. Pick one to see that mix, or tap anywhere to go back.
					</>
				) : (
					'Tap one to see what it was combined with.'
				)}
			</p>
			<Sources className="mt-3" list={['erowid', 'pw', 'tripsit']} />
			<input
				ref={searchRef}
				value={filter}
				onClick={(e) => e.stopPropagation()}
				onChange={(e) => setFilter(e.target.value)}
				placeholder="Search substances"
				className="rd-card mt-6 w-full px-5 py-3 text-base"
				style={{ borderRadius: 999, color: C.text, outline: 'none' }}
			/>
			{focus && <FocusPanel name={focus} onPick={onPick} onCombo={onCombo} onClose={() => setFocus(null)} />}
			{q.isLoading ? (
				<div className="rd-card mt-6 animate-pulse" style={{ height: 240 }} />
			) : (
				<div className="mt-6 grid gap-2" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(230px, 1fr))' }}>
					{list.map((r) => {
						const name = S(r.s);
						const isFocus = focus === name;
						const together = co.get(name);
						const lit = !focus || isFocus || together != null;
						return (
							<div
								key={name}
								role="button"
								tabIndex={0}
								onClick={(e) => {
									e.stopPropagation();
									if (!focus || isFocus) setFocus(isFocus ? null : name);
									else if (together != null) onCombo(focus, name);
									else setFocus(name);
								}}
								onKeyDown={(e) => e.key === 'Enter' && (e.currentTarget as HTMLElement).click()}
								className="rd-card rd-hover px-4 py-3"
								title={name}
								style={{
									cursor: 'pointer',
									opacity: lit ? 1 : 0.28,
									transform: isFocus ? 'scale(1.02)' : 'none',
									borderColor: isFocus ? C.lav : together != null ? 'rgba(217,207,255,.45)' : C.line,
									background: isFocus ? 'rgba(217,207,255,.16)' : undefined,
									transition: 'opacity .3s ease, transform .3s ease, border-color .3s ease, background .3s ease',
								}}
							>
								<div className="flex items-center gap-3">
									<ClassIcon cls={classOf(name)} size={20} color={isFocus ? C.text : C.lav} />
									<span className="font-semibold" style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
										{short(name)}
									</span>
									<span className="ml-auto text-xs tabular-nums" style={{ color: C.faint, whiteSpace: 'nowrap' }}>
										{focus && !isFocus && together != null ? `${together} together` : `${N(r.n)} reports`}
									</span>
								</div>
							</div>
						);
					})}
				</div>
			)}
			<Err q={q} />
		</section>
	);
}

// Slim timeline for the dock: the strip itself is coloured by mood, thin bands above show when each drug is
// active, dots below are time marks. Drag or tap anywhere to scrub.
const moodColor = (v: number) => (v > 0.15 ? C.mint : v < -0.15 ? C.coral : C.lav);
function MiniTimeline({
	xMax,
	x,
	onScrub,
	mood,
	drugs,
	ticks,
	flags = [],
}: {
	xMax: number;
	x: number;
	onScrub: (x: number) => void;
	mood: Pt[];
	drugs: Series[];
	ticks: { x: number; on: boolean; active: boolean }[];
	flags?: { x: number; label: string; on: boolean }[];
}) {
	const ref = useRef<HTMLDivElement | null>(null);
	const dragging = useRef(false);
	const [w, setW] = useState(300);
	useEffect(() => {
		const el = ref.current;
		if (!el) return;
		const ro = new ResizeObserver(([e]) => setW(Math.max(120, e.contentRect.width)));
		ro.observe(el);
		return () => ro.disconnect();
	}, []);
	const pad = 9;
	const sx = (v: number) => pad + (clamp(v, 0, xMax) / xMax) * (w - 2 * pad);
	const scrubAt = (clientX: number) => {
		const r = ref.current!.getBoundingClientRect();
		onScrub(clamp(((clientX - r.left - pad) / (w - 2 * pad)) * xMax, 0, xMax));
	};
	const bands = drugs.slice(0, 4);
	const bandH = 11, bandGap = 3;
	const stripY = 4 + bands.length * (bandH + bandGap) + 4;
	const H = stripY + 10 + 12 + (flags.length ? 13 : 0);
	// Turning-point labels under the strip; skip any that would overlap the one before.
	let flagRight = -Infinity;
	const shownFlags = flags.filter((f) => {
		const x0 = sx(f.x) - 2, x1 = x0 + f.label.length * 5.6 + 4;
		if (x0 < flagRight + 6 || x1 > w) return false;
		flagRight = x1;
		return true;
	});
	const stops = mood.length ? mood : [{ x: 0, y: 0 }, { x: xMax, y: 0 }];
	const knobV = interp(mood, x) ?? 0;
	return (
		<div ref={ref} style={{ width: '100%', minWidth: 0, userSelect: 'none' }}>
			<svg
				width={w}
				height={H}
				style={{ display: 'block', touchAction: 'pan-y', cursor: 'ew-resize', overflow: 'visible' }}
				onPointerDown={(e) => {
					e.preventDefault();
					dragging.current = true;
					(e.currentTarget as SVGSVGElement).setPointerCapture(e.pointerId);
					scrubAt(e.clientX);
				}}
				onPointerMove={(e) => dragging.current && scrubAt(e.clientX)}
				onPointerUp={() => (dragging.current = false)}
				onPointerCancel={() => (dragging.current = false)}
				role="slider"
				aria-label="Time since first dose"
				aria-valuemin={0}
				aria-valuemax={xMax}
				aria-valuenow={x}
				tabIndex={0}
				onKeyDown={(e) => {
					if (e.key === 'ArrowRight') onScrub(clamp(x + xMax / 100, 0, xMax));
					if (e.key === 'ArrowLeft') onScrub(clamp(x - xMax / 100, 0, xMax));
				}}
			>
				<defs>
					<linearGradient id="mini-mood" gradientUnits="userSpaceOnUse" x1={pad} x2={w - pad} y1="0" y2="0">
						{stops.map((p, i) => (
							<stop key={i} offset={`${(100 * clamp(p.x, 0, xMax)) / xMax}%`} stopColor={moodColor(p.y)} />
						))}
					</linearGradient>
				</defs>
				{bands.map((s, i) => {
					const on = s.points.filter((p) => p.y > 0.15);
					if (!on.length) return null;
					const x0 = sx(on[0].x), bw = Math.max(6, sx(on[on.length - 1].x) - x0), y = 4 + i * (bandH + bandGap);
					return (
						<g key={s.key}>
							<title>{short(s.label)} usually active here</title>
							<rect x={x0} y={y} width={bw} height={bandH} rx={bandH / 2} fill={s.color} opacity={0.85} />
							{bw > 46 && (
								<text x={x0 + 6} y={y + 8.2} fontSize="8.5" fontWeight="700" fill={C.deep}>
									{short(s.label)}
								</text>
							)}
						</g>
					);
				})}
				<rect x={pad} y={stripY} width={w - 2 * pad} height={10} rx={5} fill="rgba(255,255,255,.1)" />
				<rect x={pad} y={stripY} width={Math.max(0, sx(x) - pad)} height={10} rx={5} fill="url(#mini-mood)" />
				<rect x={sx(x)} y={stripY} width={Math.max(0, w - pad - sx(x))} height={10} rx={5} fill="url(#mini-mood)" opacity={0.28} />
				{ticks.map((tk, i) => (
					<circle key={i} cx={sx(tk.x)} cy={stripY + 17} r={tk.active ? 2.6 : 1.8} fill={tk.on ? '#fff' : 'rgba(255,255,255,.35)'} />
				))}
				{shownFlags.map((f) => (
					<g key={f.label} opacity={f.on ? 1 : 0.45}>
						<line x1={sx(f.x)} x2={sx(f.x)} y1={stripY + 10} y2={stripY + 22} stroke="#fff" strokeOpacity="0.5" />
						<text x={sx(f.x) + 3} y={stripY + 31} fontSize="9.5" fontWeight="700" fill="#fff" style={{ letterSpacing: '.04em' }}>
							{f.label}
						</text>
					</g>
				))}
				<line x1={sx(x)} x2={sx(x)} y1={2} y2={stripY} stroke="#fff" strokeOpacity="0.55" strokeWidth="1.5" />
				<circle cx={sx(x)} cy={stripY + 5} r={8.5} fill="#fff" stroke={moodColor(knobV)} strokeWidth={3} />
			</svg>
		</div>
	);
}

// A plain description built from the structured fields and the reports. PsychonautWiki "summaries" are mostly
// page furniture ("Summary sheet: …", "Not to be confused with …"); what's left of them is usually a safety note.
function describeSubstance(name: string, r: Record<string, unknown>, timing: Record<string, unknown>[]) {
	const t = timing.find((x) => S(x.sub) === name && S(x.route) === '*');
	const cls = L(r.cls).map((c) => c.toLowerCase().replace(/s$/, ''));
	const chem = L(r.chem).filter((c) => !/^substituted /i.test(c) || L(r.chem).length === 1);
	const kind = [cls.join(' and '), chem[0] ? `from the ${chem[0].toLowerCase()} family` : ''].filter(Boolean).join(' ');
	const article = /^[aeiou]/i.test(kind) ? 'An' : 'A';
	const kindLine = kind ? `${article} ${kind}.` : '';
	const desc = [
		kindLine,
		t ? `In reports, people usually notice it within ${fmtDur(N(t.on_m))}, feel it most around ${fmtDur(N(t.pk_m))}, and it fades by about ${fmtDur(N(t.end_m))}.` : '',
	].filter(Boolean).join(' ');
	// The safety note: MAOIs first (TripSit's grouping), then a summary that actually reads as one, then toxicity.
	const summary = sentences(S(r.summary).replace(/\[\d+\]/g, '').replace(/Summary sheet:.*$/i, '').replace(/Not to be confused with[^.]*\./gi, '').trim(), 2);
	const tox = L(r.tox).find((x) => /lethal|danger|mixed|combined/i.test(x));
	const warning = r.maoi
		? 'It’s an MAOI, which makes it dangerous with many other drugs, including MDMA, many stimulants and antidepressants. Always check a combination before mixing.'
		: summary.length > 20 && /fatal|overdose|lethal|danger|risk|caution|poison|toxic|serotonin|avoid|death|combin/i.test(summary)
			? summary
			: tox
				? `${tox[0].toUpperCase()}${tox.slice(1)}.`
				: '';
	const aka = L(r.aka).filter((a) => a.toLowerCase() !== name.toLowerCase()).slice(0, 6);
	return { desc, kindLine, warning, aka, timing: t };
}

// How one dose usually plays out, as a shape: nothing → first effects → strongest → fading. The three moments are
// marked on the curve and spelled out underneath, so the numbers read as a timeline rather than three stats.
function PhaseStrip({ on, pk, end }: { on: number; pk: number; end: number }) {
	const span = end * 1.12;
	const x = (v: number) => (100 * v) / span;
	const pts: [number, number][] = [
		[0, 0],
		[on, 0.18],
		[pk, 1],
		[pk + (end - pk) * 0.3, 0.8],
		[end, 0.22],
		[span, 0],
	];
	const H = 54;
	const path = pts.map(([v, y], i) => `${i ? 'L' : 'M'}${x(v) * 10},${H - y * (H - 8)}`).join(' ');
	const marks = [
		{ v: on, label: 'Kicks in', color: C.lav },
		{ v: pk, label: 'Strongest', color: C.cyan },
		{ v: end, label: 'Mostly gone', color: C.faint },
	];
	return (
		<div>
			<div className="relative" style={{ height: H }}>
				<svg viewBox={`0 0 1000 ${H}`} preserveAspectRatio="none" width="100%" height={H} style={{ display: 'block', overflow: 'visible' }} aria-hidden>
					<defs>
						<linearGradient id="phase-fill" x1="0" x2="0" y1="0" y2="1">
							<stop offset="0%" stopColor={C.cyan} stopOpacity="0.35" />
							<stop offset="100%" stopColor={C.cyan} stopOpacity="0.02" />
						</linearGradient>
					</defs>
					<path d={`${path} L1000,${H} L0,${H} Z`} fill="url(#phase-fill)" />
					<path d={path} fill="none" stroke={C.cyan} strokeWidth="2" vectorEffect="non-scaling-stroke" />
					<line x1="0" x2="1000" y1={H} y2={H} stroke="rgba(255,255,255,.2)" vectorEffect="non-scaling-stroke" />
					{marks.map((m) => (
						<line key={m.label} x1={x(m.v) * 10} x2={x(m.v) * 10} y1="0" y2={H} stroke={m.color} strokeDasharray="3 4" strokeOpacity="0.7" vectorEffect="non-scaling-stroke" />
					))}
				</svg>
				{marks.map((m) => (
					<span key={m.label} className="absolute rounded-full" style={{ left: `${x(m.v)}%`, bottom: -5, width: 10, height: 10, marginLeft: -5, background: m.color, boxShadow: `0 0 0 3px ${C.deep}` }} />
				))}
			</div>
			<div className="mt-1 flex justify-between text-xs" style={{ color: C.faint }}>
				<span>Dose</span>
				<span>{fmtDur(span)}</span>
			</div>
			<div className="mt-3 grid grid-cols-3 gap-4">
				{marks.map((m) => (
					<div key={m.label}>
						<div className="flex items-center gap-2">
							<span className="rd-dot" style={{ width: 9, height: 9, background: m.color }} />
							<span className="rd-label" style={{ color: C.soft }}>{m.label}</span>
						</div>
						<div className="mt-0.5 text-2xl font-light" style={{ letterSpacing: '-0.02em' }}>
							{m.label === 'Mostly gone' ? 'by ' : '~'}
							{fmtDur(m.v)}
						</div>
					</div>
				))}
			</div>
		</div>
	);
}

// The top of a substance's own page: what it is (and what people call it), how a dose usually plays out, what to
// watch for, what people feel. Tolerance and what it's mixed with sit in their own cards below.
function SubstanceOverview({ name, onCombo }: { name: string; onCombo: (a: string, b: string) => void }) {
	const detailQ = useSQLQuery(substanceDetailSQL(name));
	const timingQ = useSQLQuery(timingSQL([name]));
	const r = rows(detailQ)[0];
	if (detailQ.isLoading || timingQ.isLoading) return <div className="rd-card mt-6 animate-pulse" style={{ height: 360 }} />;
	if (!r) return null;
	const { kindLine, warning, aka, timing: t } = describeSubstance(name, r, rows(timingQ));
	return (
		<>
			{aka.length > 0 && (
				<p className="mt-3 text-lg" style={{ color: C.soft }}>
					Also called{' '}
					{aka.map((a, i) => (
						<span key={a}>
							{i > 0 && <span style={{ color: C.faint }}>{i === aka.length - 1 ? ' or ' : ', '}</span>}
							<span style={{ color: '#fff', fontWeight: 600, whiteSpace: 'nowrap' }}>{a}</span>
						</span>
					))}
				</p>
			)}
			<div className="rd-card rd-in mt-6 p-6 sm:p-7">
				<div className="grid gap-8 lg:grid-cols-[minmax(0,1.35fr)_minmax(0,1fr)]">
					<div className="min-w-0">
						{kindLine && <p style={{ fontFamily: SERIF, fontSize: 21, lineHeight: 1.45 }}>{kindLine}</p>}
						{t ? (
							<div className="mt-5">
								<div className="rd-label mb-2">How a dose usually plays out</div>
								<PhaseStrip on={N(t.on_m)} pk={N(t.pk_m)} end={N(t.end_m)} />
							</div>
						) : (
							<p className="mt-3 text-sm" style={{ color: C.faint }}>Not enough closely read reports to time it yet.</p>
						)}
					</div>
					<div className="min-w-0">
						<div className="rd-label mb-3">At a glance</div>
						<ul className="grid gap-3 text-sm" style={{ lineHeight: 1.45 }}>
							{warning && (
								<li className="flex items-start gap-2.5" title={warning}>
									<AlertTriangle size={16} color={C.coral} style={{ flexShrink: 0, marginTop: 1 }} />
									<span style={{ color: '#fff', display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{warning}</span>
								</li>
							)}
							{S(r.addiction) && (
								<li className="flex items-start gap-2.5">
									{/high|very|extreme|moderate|addictive/i.test(S(r.addiction)) && !/^non|not /i.test(S(r.addiction)) ? (
										<AlertTriangle size={16} color={C.amber} style={{ flexShrink: 0, marginTop: 1 }} />
									) : (
										<Check size={16} color={C.mint} style={{ flexShrink: 0, marginTop: 1 }} />
									)}
									<span style={{ color: C.soft }}>{S(r.addiction)[0].toUpperCase() + S(r.addiction).slice(1)}</span>
								</li>
							)}
							{(S(r.tolerance_zero) || S(r.tolerance_full)) && (
								<li className="flex items-start gap-2.5">
									<RotateCcw size={15} color={C.lav} style={{ flexShrink: 0, marginTop: 2 }} />
									<span style={{ color: C.soft }}>
										{S(r.tolerance_zero)
											? `Tolerance resets ${S(r.tolerance_zero).replace(/^after\s+/i, 'after ').replace(/^(?=\d)/, 'after ')}`
											: `Tolerance ${S(r.tolerance_full).replace(/^with\s+/i, 'builds with ')}`}
									</span>
								</li>
							)}
							<li className="flex items-start gap-2.5">
								<Calendar size={15} color={C.faint} style={{ flexShrink: 0, marginTop: 2 }} />
								<span style={{ color: C.faint }}>
									{N(r.n_reports).toLocaleString()} reports · {N(r.n_read)} read closely
								</span>
							</li>
						</ul>
					</div>
				</div>
				{L(r.effects).length > 0 && (
					<div className="mt-7 border-t pt-5" style={{ borderColor: C.line }}>
						<div className="rd-label mb-3">What people mostly feel</div>
						<div className="flex flex-wrap gap-2">
							{L(r.effects).map((e) => (
								<EffectTag key={e} name={e} />
							))}
						</div>
					</div>
				)}
			</div>
			<div className={`mt-6 grid gap-6 ${L(r.cross_tol).length > 0 ? 'lg:grid-cols-2' : ''}`}>
				{L(r.cross_tol).length > 0 && (
					<div className="rd-card content-start p-6">
						<CrossTol name={name} />
					</div>
				)}
				<div className="rd-card content-start p-6">
					<CombosList name={name} onCombo={onCombo} />
				</div>
			</div>
		</>
	);
}

