// ── Pair answers ──────────────────────────────────────────────────
// Bite-sized answers for a combination: how long, how it went, what changes, what people took first.

const pairGroupsCTE = (a: string, b: string) => `
rs AS (
  SELECT report_id, list(DISTINCT canonical_substance) AS subs
  FROM ${DB}."report_doses" WHERE canonical_substance IS NOT NULL GROUP BY 1
),
grp AS (
  SELECT report_id, 'Together' AS grp FROM rs WHERE list_has_all(subs, ['${esc(a)}', '${esc(b)}'])
  UNION ALL
  SELECT report_id, subs[1] AS grp FROM rs WHERE len(subs) = 1 AND subs[1] IN ('${esc(a)}', '${esc(b)}')
)`;

const pairSummarySQL = (a: string, b: string) => `
WITH ${pairGroupsCTE(a, b)},
val AS (
  SELECT report_id, avg(valence) AS v FROM ${DB}."timeline_sentiment"
  WHERE report_id IN (SELECT report_id FROM grp) GROUP BY 1
)
SELECT g.grp, count(*) AS n, count(e.report_id) AS n_llm,
  avg((e.overall_sentiment = 'positive')::INT) AS pos, avg((e.overall_sentiment = 'negative')::INT) AS neg,
  avg(e.would_repeat::INT) AS rep, count(e.would_repeat) AS n_rep, avg(val.v) AS v, count(val.v) AS n_val
FROM grp g LEFT JOIN val USING (report_id) LEFT JOIN ${DB}."llm_extractions" e USING (report_id)
GROUP BY g.grp`;

const pairEffectsSQL = (a: string, b: string) => `
WITH ${pairGroupsCTE(a, b)},
den AS (
  SELECT grp, count(DISTINCT report_id) AS n FROM grp
  WHERE report_id IN (SELECT report_id FROM ${DB}."llm_observations") GROUP BY grp
),
eff AS (
  SELECT DISTINCT g.grp, e.report_id, e.effect_name
  FROM grp g JOIN ${DB}."llm_observation_effects" e USING (report_id)
  WHERE e.confidence <> 'low'
)
SELECT eff.grp, eff.effect_name, count(*) AS c, any_value(den.n) AS n, 100.0 * count(*) / any_value(den.n) AS share
FROM eff JOIN den USING (grp)
GROUP BY eff.grp, eff.effect_name`;

const pairSeqSQL = (a: string, b: string) => `
WITH tog AS (
  SELECT report_id FROM ${DB}."report_doses" WHERE canonical_substance = '${esc(a)}'
  INTERSECT SELECT report_id FROM ${DB}."report_doses" WHERE canonical_substance = '${esc(b)}'
),
first_t AS (
  SELECT d.report_id, d.canonical_substance AS sub, min(d.t_offset) AS t
  FROM ${DB}."report_doses" d JOIN tog USING (report_id)
  WHERE d.canonical_substance IN ('${esc(a)}', '${esc(b)}') AND d.t_offset IS NOT NULL
  GROUP BY 1, 2
),
paired AS (
  SELECT x.report_id, x.t AS ta, y.t AS tb FROM first_t x JOIN first_t y USING (report_id)
  WHERE x.sub = '${esc(a)}' AND y.sub = '${esc(b)}'
)
SELECT count(*) AS n,
  avg((ta < tb)::INT) AS a_first, avg((tb < ta)::INT) AS b_first, avg((ta = tb)::INT) AS same,
  median(abs(tb - ta)) FILTER (WHERE ta <> tb) AS gap
FROM paired`;

const pct0 = (v: unknown) => `${Math.round(100 * N(v))}%`;
const wordTone = (v: number) => (v > 0.12 ? 'upbeat' : v > 0.04 ? 'mostly positive' : v > -0.04 ? 'neutral' : v > -0.12 ? 'mostly negative' : 'low');

function AnswerCard({ q, children }: { q: string; children: React.ReactNode }) {
	return (
		<div className="rd-card rd-in p-5 sm:p-6">
			<div className="rd-label">{q}</div>
			<div className="mt-3">{children}</div>
		</div>
	);
}

function PairAnswers({ a, b, timingQ, moodQ, summaryQ, effectsQ, seqQ }: { a: string; b: string; timingQ: Q; moodQ: Q; summaryQ: Q; effectsQ: Q; seqQ: Q }) {
	// 1. How long
	const tim = rows(timingQ);
	const tOf = (s: string) => tim.find((r) => S(r.sub) === s && S(r.route) === '*');
	const ta = tOf(a), tb = tOf(b);
	const lastLine = (s: string, t?: Record<string, unknown>) => (t ? `${short(s)} usually peaks around ${fmtDur(N(t.pk_m))} and fades by about ${fmtDur(N(t.end_m))}` : `${short(s)}: not enough reports to time it`);
	const overlap = ta && tb ? Math.min(N(ta.end_m), N(tb.end_m)) : null;

	// 2. How it went
	const sum = new Map(rows(summaryQ).map((r) => [S(r.grp), r]));
	const groups = [
		{ key: 'Together', label: 'Together' },
		{ key: a, label: `${short(a)} alone` },
		{ key: b, label: `${short(b)} alone` },
	];

	// 3. What changes
	const share = new Map<string, Map<string, { s: number; c: number }>>();
	for (const r of rows(effectsQ)) {
		const e = S(r.effect_name);
		if (!share.has(e)) share.set(e, new Map());
		share.get(e)!.set(S(r.grp), { s: N(r.share), c: N(r.c) });
	}
	const togN = N(rows(effectsQ).find((r) => S(r.grp) === 'Together')?.n);
	const diffs = [...share.entries()]
		.map(([e, g]) => {
			const t = g.get('Together');
			const alone = Math.max(g.get(a)?.s ?? 0, g.get(b)?.s ?? 0);
			return { e, t: t?.s ?? 0, c: t?.c ?? 0, d: (t?.s ?? 0) - alone };
		})
		.filter((x) => x.c >= 2);
	const more = diffs.filter((x) => x.d >= 8).sort((p, q) => q.d - p.d).slice(0, 4);
	const less = diffs.filter((x) => x.d <= -8).sort((p, q) => p.d - q.d).slice(0, 3);

	// 4. Order
	const seq = rows(seqQ)[0];

	return (
		<div className="mt-6 grid gap-4" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 420px), 1fr))' }}>
			<AnswerCard q="How long does it last?">
				{timingQ.isLoading ? (
					<div className="animate-pulse" style={{ height: 80 }} />
				) : (
					<>
						<p style={{ fontFamily: SERIF, fontSize: 19, lineHeight: 1.5 }}>
							{lastLine(a, ta)}; {lastLine(b, tb).replace(/^./, (c) => c.toLowerCase())}.
							{overlap != null && ` Taken at the same time, they usually overlap for about the first ${fmtDur(overlap)}.`}
						</p>
						<PairTypical a={a} b={b} timingQ={timingQ} moodQ={moodQ} bare />
					</>
				)}
			</AnswerCard>

			<AnswerCard q="How did it go?">
				{summaryQ.isLoading ? (
					<div className="animate-pulse" style={{ height: 120 }} />
				) : (
					<div className="grid gap-4">
						{groups.map((g) => {
							const r = sum.get(g.key);
							const n = N(r?.n_llm);
							return (
								<div key={g.key}>
									<div className="flex items-baseline justify-between gap-2 text-sm">
										<span className="font-semibold" style={{ whiteSpace: 'nowrap' }}>{g.label}</span>
										<span style={{ color: C.faint, whiteSpace: 'nowrap' }}>
											{N(r?.n)} reports{n ? ` · ${n} read closely` : ''}
										</span>
									</div>
									{n >= 3 ? (
										<>
											<div className="mt-2 flex overflow-hidden rounded-full" style={{ height: 8, background: 'rgba(255,255,255,.08)' }}>
												<div style={{ width: pct0(r?.pos), background: C.mint }} />
												<div style={{ flex: 1 }} />
												<div style={{ width: pct0(r?.neg), background: C.coral }} />
											</div>
											<div className="mt-1 flex justify-between text-xs" style={{ color: C.soft }}>
												<span style={{ color: C.mint }}>{pct0(r?.pos)} good</span>
												{N(r?.n_rep) >= 3 && <span>{pct0(r?.rep)} would do it again</span>}
												<span style={{ color: C.coral }}>{pct0(r?.neg)} rough</span>
											</div>
										</>
									) : (
										<div className="mt-1 text-xs" style={{ color: C.faint }}>
											{N(r?.n_val) ? `Wording reads ${wordTone(N(r?.v))} · too few close reads for a score` : 'Not enough reports yet'}
										</div>
									)}
								</div>
							);
						})}
					</div>
				)}
			</AnswerCard>

			<AnswerCard q="What's different together?">
				{effectsQ.isLoading ? (
					<div className="animate-pulse" style={{ height: 100 }} />
				) : togN < 3 ? (
					<p className="text-sm" style={{ color: C.soft }}>Too few closely read reports with both to compare.</p>
				) : more.length + less.length === 0 ? (
					<p className="text-sm" style={{ color: C.soft }}>Nothing stands out — together it reads much like each one alone.</p>
				) : (
					<div className="grid gap-4">
						{more.length > 0 && (
							<div>
								<div className="mb-2 text-sm" style={{ color: C.soft }}>Mentioned more together</div>
								<div className="flex flex-wrap gap-2">
									{more.map((x) => (
										<span key={x.e} className="flex items-center gap-1.5">
											<EffectTag name={x.e} />
											<span className="text-xs tabular-nums" style={{ color: C.mint }}>+{Math.round(x.d)}</span>
										</span>
									))}
								</div>
							</div>
						)}
						{less.length > 0 && (
							<div>
								<div className="mb-2 text-sm" style={{ color: C.soft }}>Mentioned less together</div>
								<div className="flex flex-wrap gap-2">
									{less.map((x) => (
										<span key={x.e} className="flex items-center gap-1.5">
											<EffectTag name={x.e} />
											<span className="text-xs tabular-nums" style={{ color: C.coral }}>{Math.round(x.d)}</span>
										</span>
									))}
								</div>
							</div>
						)}
						<div className="text-xs" style={{ color: C.faint }}>Change in % of reports mentioning it, vs. whichever drug alone mentions it more. Based on {togN} close reads.</div>
					</div>
				)}
			</AnswerCard>

			<AnswerCard q="What did people take first?">
				{seqQ.isLoading ? (
					<div className="animate-pulse" style={{ height: 60 }} />
				) : !seq || N(seq.n) < 3 ? (
					<p className="text-sm" style={{ color: C.soft }}>Not enough reports say when each one was taken.</p>
				) : (
					(() => {
						const af = N(seq.a_first), bf = N(seq.b_first), same = N(seq.same);
						const first = af >= bf ? a : b, second = first === a ? b : a;
						const lead = Math.max(af, bf);
						return (
							<p style={{ fontFamily: SERIF, fontSize: 19, lineHeight: 1.5 }}>
								{same > lead
									? `Most people took them at about the same time (${pct0(same)}).`
									: `Most people started with ${short(first)} (${pct0(lead)}), then took ${short(second)}${seq.gap != null ? ` about ${fmtDur(N(seq.gap))} later` : ''}.`}
								<span className="block text-sm" style={{ color: C.faint, fontFamily: SANS, marginTop: 6 }}>
									From {N(seq.n)} reports that give a time for both.
								</span>
							</p>
						);
					})()
				)}
			</AnswerCard>
		</div>
	);
}

// When few reports with both were read closely: each drug's own typical curve (both taken at 0:00), plus the tone of
// the writing across every report with both.
function PairTypical({ a, b, timingQ, moodQ, bare }: { a: string; b: string; timingQ: Q; moodQ: Q; bare?: boolean }) {
	const [x, setX] = useState(1);
	const exp = useMemo(
		() =>
			expectedCurves(
				[a, b].map((sub) => ({ sub, amount: '', route: '', t: 0, assumed: true })),
				rows(timingQ),
			),
		// eslint-disable-next-line react-hooks/exhaustive-deps
		[timingQ.data, a, b],
	);
	const xMax = clamp(Math.max(2, exp.end) * 1.05, 2, 24);
	const w = 24 / SLICES;
	const mood = rows(moodQ)
		.filter((r) => N(r.n) >= 3 && (N(r.bin) + 0.5) * w <= xMax)
		.sort((p, q) => N(p.bin) - N(q.bin))
		.map((r) => ({ x: (N(r.bin) + 0.5) * w, y: clamp(N(r.v) * 2.5, -1, 1) }));
	const total = N(rows(moodQ)[0]?.total);
	const lanes: Lane[] = [
		...(mood.length >= 3 ? [{ label: 'Mood (from the wording)', height: 60, min: -1.05, max: 1.05, diverging: true, linear: true, series: [{ key: 'm', label: 'Mood', color: C.lav, points: mood }] }] : []),
		...exp.series.map((s) => ({ label: short(s.label), sub: s.sub, color: s.color, height: 44, min: 0, max: 1.15, series: [s] })),
	];
	if (timingQ.isLoading || moodQ.isLoading) return <div className="rd-card mt-6 animate-pulse" style={{ height: 260 }} />;
	if (!lanes.length) return <p className="rd-card mt-6 p-5 text-sm" style={{ color: C.soft }}>Not enough data on this pair yet to sketch a timeline.</p>;
	const both = exp.series.filter((s) => (interp(s.points, x) ?? 0) > 0.05 && x >= s.points[0].x && x <= s.points[s.points.length - 1].x).map((s) => short(s.label));
	if (bare)
		return (
			<div className="mt-4">
				<ScrubChart id="pairtyp" lanes={lanes} xMax={xMax} x={x} onScrub={setX} xLabels={niceTicks(xMax).map((h) => ({ x: h, label: tickLabel(h) }))} />
				<p className="mt-3 text-sm" style={{ color: C.soft }}>
					<span className="rd-label mr-2">Around {fmtT(x)}</span>
					{both.length >= 2 ? `both are usually active` : both.length === 1 ? `mostly ${both[0]}` : 'both usually worn off'}
				</p>
			</div>
		);
	return (
		<div className="rd-card mt-6 p-5 sm:p-6">
			<div className="flex flex-wrap items-baseline justify-between gap-2">
				<h2 className="text-lg font-semibold">Typical timeline if taken together</h2>
				<span className="text-sm" style={{ color: C.faint }}>drag across</span>
			</div>
			<p className="mt-1 text-sm" style={{ color: C.faint }}>
				Each drug's usual curve from its own reports, both starting at 0:00{total ? `, with the tone of all ${total} reports that include both` : ''}.
			</p>
			<div className="mt-5">
				<ScrubChart id="pairtyp" lanes={lanes} xMax={xMax} x={x} onScrub={setX} xLabels={niceTicks(xMax).map((h) => ({ x: h, label: tickLabel(h) }))} />
			</div>
			<p className="mt-4 text-sm" style={{ color: C.soft }}>
				<span className="rd-label mr-2">Around {fmtT(x)}</span>
				{both.length >= 2 ? `both are usually active — ${both.join(' + ')}` : both.length === 1 ? `mostly ${both[0]}` : 'both usually worn off'}
			</p>
			{exp.missing.length > 0 && <p className="mt-2 text-xs" style={{ color: C.faint }}>No timing data yet for {exp.missing.map(short).join(', ')}.</p>}
		</div>
	);
}

// ── Reports for a substance ───────────────────────────────────────

// Readable tick spacing for a time axis of `h` hours.
const niceTicks = (h: number) => {
	const steps = [5 / 60, 10 / 60, 0.25, 0.5, 1, 2, 3, 4, 6];
	const step = steps.find((s) => h / s <= 7) ?? 6;
	return Array.from({ length: Math.floor(h / step + 1e-9) + 1 }, (_, i) => i * step);
};
const tickLabel = (h: number) => (h === 0 ? '0' : h < 1 ? `${Math.round(h * 60)}m` : `${Math.round(h * 10) / 10}h`);

function ReportsStep({ sub, withSub, only, setOnly, onCombo, pairQ, pairTimingQ, pairMoodQ, pairSummaryQ, pairEffectsQ, pairSeqQ, q, kq, curveQ, denQ, horizon, onOpen }: { sub: string; withSub: string | null; only: boolean; setOnly: (v: boolean) => void; onCombo: (a: string, b: string) => void; pairQ: Q; pairTimingQ: Q; pairMoodQ: Q; pairSummaryQ: Q; pairEffectsQ: Q; pairSeqQ: Q; q: Q; kq: Q; curveQ: Q; denQ: Q; horizon: number; onOpen: (id: string) => void }) {
	const list = rows(q);
	const k = rows(kq)[0];
	const [x, setX] = useState<number | null>(null);
	const { open } = useContext(OpenCtx);
	const w = horizon / SLICES;
	const cursor = x ?? horizon * 0.3;
	const { series, denom } = useMemo(() => {
		const denom = new Map(rows(denQ).map((r) => [N(r.bin), N(r.n)]));
		const by = new Map<string, Map<number, number>>();
		const totals = new Map<string, number>();
		for (const r of rows(curveQ)) {
			const n = S(r.effect_name);
			if (!by.has(n)) by.set(n, new Map());
			by.get(n)!.set(N(r.bin), N(r.c));
			totals.set(n, (totals.get(n) ?? 0) + N(r.c));
		}
		const names = [...totals.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([n]) => n);
		const series: Series[] = names.map((n, i) => ({
			key: `s${i}`,
			label: n,
			color: SERIES[i % SERIES.length],
			points: Array.from({ length: SLICES }, (_, b) => b)
				.filter((b) => (denom.get(b) ?? 0) >= 3)
				.map((b) => ({ x: (b + 0.5) * w, y: (100 * (by.get(n)?.get(b) ?? 0)) / (denom.get(b) ?? 1) })),
		}));
		return { series, denom };
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [curveQ.data, denQ.data, w]);
	const moodPts = rows(denQ).filter((r) => N(r.n) >= 3).sort((a, b) => N(a.bin) - N(b.bin)).map((r) => ({ x: (N(r.bin) + 0.5) * w, y: N(r.mood) }));
	const dataEnd = Math.max(0, ...series.flatMap((x) => x.points.map((p) => p.x)), ...moodPts.map((p) => p.x)) + w / 2;
	const chartMax = clamp(dataEnd, Math.min(horizon, w * 4), horizon);
	const slice = clamp(Math.floor(cursor / w), 0, SLICES - 1);
	const readout = series.map((s) => ({ ...s, v: interp(s.points, cursor) })).filter((r) => r.v != null).sort((a, b) => (b.v as number) - (a.v as number));
	const shuffle = () => list.length && onOpen(S(list[Math.floor(Math.random() * list.length)].report_id));
	// A dangerous or unsafe pair tints the whole page, so the risk is felt before anything is read.
	const pairNote = withSub ? rows(pairQ)[0] : undefined;
	const tolQ = useSQLQuery(tolPairsSQL(withSub ? [sub, withSub] : []), { enabled: !!withSub });
	const tolShared = withSub ? rows(tolQ)[0] : undefined;
	const risk = pairNote ? N(pairNote.sev) : 0;

	return (
		<section className="rd-fade" style={{ position: 'relative', zIndex: 0 }}>
			{risk >= 2 && <div aria-hidden className="rd-tint" style={{ background: RISK_TINT[risk] }} />}
			<h1 className="flex flex-wrap items-center gap-x-3 gap-y-1 text-4xl font-semibold sm:text-5xl">
				{[sub, ...(withSub ? [withSub] : [])].map((n, i) => (
					<span key={n} className="inline-flex items-center gap-3" style={{ whiteSpace: 'nowrap' }}>
						{i > 0 && <span style={{ color: risk >= 2 ? RISK[risk].c : C.faint, fontWeight: 300 }}>+</span>}
						<button title={n} onClick={() => open({ kind: 'substance', name: n })} className="inline-flex items-center gap-3">
							<SubstanceIcon name={n} />
							{short(n)}
						</button>
					</span>
				))}
			</h1>
			{!withSub && <SubstanceOverview name={sub} onCombo={onCombo} />}
			<div className={`${withSub ? "mt-4" : "mt-12"} flex flex-wrap items-center gap-2`}>
				{[false, true].map((v) => (
					<button key={String(v)} className="rd-nav" aria-current={only === v ? 'page' : undefined} onClick={() => setOnly(v)} style={{ fontSize: 13, padding: '5px 12px', border: `1px solid ${C.line}` }}>
						{v ? (withSub ? 'Only these two' : `Only ${short(sub)}`) : withSub ? 'Any reports with both' : 'Any reports with it'}
					</button>
				))}
				<span className="text-xs" style={{ color: C.faint }}>{only ? 'Nothing else taken' : 'May include other substances'}</span>
			</div>
			<Sources className="mt-4" list={['erowid', 'sei', 'pw', ...(withSub ? ['tripsit' as const] : [])]} />
			{withSub && (
				<div className="rd-card rd-in mt-6 p-5" style={risk >= 2 ? { background: RISK[risk].bg, borderColor: RISK[risk].c, padding: 28 } : undefined}>
					{(() => {
						const p = pairNote;
						const sev = risk;
						const look = sev >= 2 ? RISK[sev] : sev === 1 ? { c: C.lav, t: 'Use caution' } : p?.status ? { c: C.mint, t: S(p.status) } : null;
						return pairQ.isLoading ? (
							<span style={{ color: C.faint }}>Checking interaction notes…</span>
						) : look ? (
							<div className="flex items-start gap-4">
								{sev >= 2 ? (
									<span className="flex items-center justify-center" style={{ width: 44, height: 44, borderRadius: 999, background: `${look.c}26`, flexShrink: 0 }}>
										<AlertTriangle size={22} color={look.c} />
									</span>
								) : (
									<AlertTriangle size={20} color={look.c} style={{ flexShrink: 0, marginTop: 2 }} />
								)}
								<div>
									<div className={sev >= 2 ? 'text-2xl font-semibold' : 'text-lg font-semibold'} style={{ color: look.c, letterSpacing: '-0.01em' }}>{look.t}</div>
									{p?.note && <p className="mt-2" style={{ fontFamily: SERIF, fontSize: 17, lineHeight: 1.5, color: C.text }}>{S(p.note)}</p>}
									<div className="mt-3 text-xs" style={{ color: C.faint }}>
										{S(p?.via) === 'TripSit' ? (
											<>
												<TripSitBadge />
											</>
										) : (
											`From interaction notes${p?.via ? ` (via ${S(p.via)})` : ''}.`
										)}
									</div>
								</div>
							</div>
						) : (
							<div className="text-sm" style={{ color: C.soft }}>No interaction note on file for this pair — that isn't the same as safe.</div>
						);
					})()}
				</div>
			)}
			{tolShared && (
				<p className="rd-in mt-3 flex items-start gap-2 text-sm" style={{ color: C.soft }}>
					<Repeat size={15} color={C.lav} style={{ flexShrink: 0, marginTop: 2 }} />
					<span>
						Shared tolerance: one taken lately makes the other feel weaker.
					</span>
				</p>
			)}
			{curveQ.isLoading || kq.isLoading ? (
				<div className="rd-card mt-6 animate-pulse" style={{ height: 320 }} />
			) : withSub ? (
				<>
					<PairAnswers a={sub} b={withSub} timingQ={pairTimingQ} moodQ={pairMoodQ} summaryQ={pairSummaryQ} effectsQ={pairEffectsQ} seqQ={pairSeqQ} />
					{N(rows(denQ)[0]?.total) >= 20 && series.length > 0 && <div className="rd-card mt-4 p-5 text-sm" style={{ color: C.faint }}>Based on {N(rows(denQ)[0]?.total)} closely read reports with both.</div>}
				</>
			) : series.length > 0 ? (
				<section className="mt-10 border-t pt-7" style={{ borderColor: C.line }}>
					<div className="flex flex-wrap items-baseline justify-between gap-2">
						<h2 className="text-2xl font-semibold">{withSub ? 'How it tends to unfold together' : 'How it tends to unfold'}</h2>
						<span className="text-sm" style={{ color: C.faint }}>From {N(rows(denQ)[0]?.total)} closely read reports · % mentioning each effect · drag across</span>
					</div>
					<div className="mt-5">
						<ScrubChart
							id="sub"
							lanes={[
								...(moodPts.length >= 3 ? [{ label: 'Mood', height: 60, min: -1.05, max: 1.05, diverging: true, linear: true, series: [{ key: 'mood', label: 'Mood', color: C.lav, points: moodPts }] }] : []),
								...series.map((s) => ({ label: s.label, color: s.color, height: 40, min: 0, max: Math.max(10, ...s.points.map((p) => p.y)) * 1.1, series: [s] })),
							]}
							xMax={chartMax}
							x={Math.min(cursor, chartMax)}
							onScrub={setX}
							xLabels={niceTicks(chartMax).map((h) => ({ x: h, label: tickLabel(h) }))}
						/>
					</div>
					<div className="mt-5">
						<span className="rd-label">
							Around {fmtT(cursor)} · {denom.get(slice) ?? 0} reports describe this
						</span>
						<div className="mt-3 flex flex-wrap gap-x-4 gap-y-2">
							{readout.map((r) => (
								<span key={r.label} className="flex items-center gap-2">
									<EffectTag name={r.label} />
									<span className="text-sm tabular-nums" style={{ color: C.faint }}>{Math.round(r.v as number)}%</span>
								</span>
							))}
						</div>
					</div>
				</section>
			) : null}

			<div className="mt-10 flex flex-wrap items-end justify-between gap-3">
				<div>
					<h2 className="text-2xl font-semibold">{withSub ? 'Stories with both' : 'Stories'}</h2>
					<p className="mt-1 text-sm" style={{ color: C.faint }}>What people went through, in their own words. Closely read ones first.</p>
				</div>
				<button onClick={shuffle} className="rd-btn flex items-center gap-2">
					<Shuffle size={15} /> Random
				</button>
			</div>
			{q.isLoading ? (
				<div className="rd-card mt-4 animate-pulse" style={{ height: 260 }} />
			) : (
				<div className="mt-4 grid gap-3" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))' }}>
					{list.map((r) => (
						<button key={S(r.report_id)} onClick={() => onOpen(S(r.report_id))} className="rd-card rd-hover p-5 text-left">
							<div className="flex items-center justify-between gap-2">
								<span className="rd-label">{r.yr != null ? N(r.yr) : 'Year unknown'}</span>
								{r.read_closely === true && <span className="text-xs font-semibold" style={{ color: C.cyan }}>Read closely</span>}
							</div>
							<p className="mt-3" style={{ fontFamily: SERIF, fontSize: 16, lineHeight: 1.6, color: C.soft }}>{S(r.opening)}…</p>
							<div className="mt-3 text-xs" style={{ color: C.faint }}>
								{N(r.n_marks)} marks · {Math.max(1, Math.round(N(r.chars) / 1200))} min read
							</div>
						</button>
					))}
				</div>
			)}
			<Err q={q} />
		</section>
	);
}

// ── Time-lapse ────────────────────────────────────────────────────

function TimelapseStep({ id, reportQ, marksQ, dosesQ, obsQ, timingQ, pairsQ, frozen }: { id: string; reportQ: Q; marksQ: Q; dosesQ: Q; obsQ: Q; timingQ: Q; pairsQ: Q; frozen: boolean }) {
	const report = rows(reportQ)[0];
	const body = S(report?.body)
		.replace(/\s*Exp Year:\s*\d{4}[\s\S]*$/, '')
		.replace(/\t/g, ' ')
		.replace(/([^\n.!?:"”)\]])\n(?![ ]*(T\s*\+|\d{1,2}[:.]\d{2}|\[|\n|[-–•*]))/g, '$1 ')
		.replace(/(?<=\w)\uFFFD(?=\w)/g, '’').replace(/\uFFFD/g, '"');
	const obs = rows(obsQ).filter((o) => o.hrs != null);
	// Prefer the close reading's moments; fall back to the automatic time marks when it can't be placed.
	const marks = useMemo(() => {
		const fromObs = locateObs(body, obs);
		return fromObs.length >= Math.max(2, obs.length * 0.4) ? fromObs : locateMarks(body, rows(marksQ));
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [body, marksQ.data, obsQ.data]);
	const byTime = useMemo(() => [...marks].sort((a, b) => a.t - b.t || a.start - b.start), [marks]);
	const doses = rows(dosesQ).map((d) => ({ sub: S(d.sub), amount: S(d.amount), route: S(d.route), t: d.t == null ? 0 : N(d.t), assumed: d.t == null }));
	const expected = useMemo(() => expectedCurves(doses, rows(timingQ)), [dosesQ.data, timingQ.data]);
	const doseSubs = [...new Set(doses.map((d) => d.sub))];
	const tolQ = useSQLQuery(tolPairsSQL(doseSubs), { enabled: doseSubs.length > 1 });
	// Every effect in the story, most mentioned first, with when it first shows up.
	const allEffects = useMemo(() => {
		const m = new Map<string, { n: number; first: number }>();
		for (const o of obs) for (const e of L(o.effects)) {
			const cur = m.get(e);
			m.set(e, { n: (cur?.n ?? 0) + 1, first: Math.min(cur?.first ?? Infinity, N(o.hrs)) });
		}
		return [...m.entries()].sort((a, b) => b[1].n - a[1].n || a[1].first - b[1].first);
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [obsQ.data]);
	const [allTags, setAllTags] = useState(false);
	// Effects that show up for the first time at each moment: where each one "became a thing".
	const newEffects = useMemo(() => {
		const seen = new Set<string>();
		const out = new Map<string, string[]>();
		for (const o of [...obs].sort((a, b) => N(a.hrs) - N(b.hrs))) {
			const fresh = L(o.effects).filter((e) => !seen.has(e));
			fresh.forEach((e) => seen.add(e));
			if (fresh.length) out.set(S(o.obs_index), fresh);
		}
		return out;
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [obsQ.data]);
	const storyEnd = Math.max(0.25, ...byTime.map((m) => m.t), ...obs.map((o) => N(o.hrs)), ...doses.map((d) => d.t));
	const [showAll, setShowAll] = useState(false);
	const fullT = Math.min(Math.max(storyEnd, expected.end), storyEnd + 12);
	const coreEnd = (() => {
		const ts = byTime.map((m) => m.t);
		for (let i = 2; i < ts.length; i++) if (ts[i] - ts[i - 1] > 6) return ts[i - 1];
		return null;
	})();
	const zoomed = coreEnd != null && !showAll;
	const maxT = zoomed ? Math.min(fullT, Math.max(coreEnd! + 4, coreEnd! * 1.15)) : fullT;

	// Turning points of the trip, each pinned to the nearest moment in the story and shown as a band in the text.
	// Kicking in is the first moment with an effect (or the expected onset), peak and coming down follow the
	// expected curve of the first thing taken, and last effects is the last moment of the main part.
	const milestones = useMemo(() => {
		const core = byTime.filter((m) => coreEnd == null || m.t <= coreEnd);
		if (core.length < 3) return [] as Milestone[];
		const first = [...doses].sort((a, b) => a.t - b.t)[0];
		const t0 = first?.t ?? 0;
		const main = expected.series.find((s) => s.label === first?.sub) ?? expected.series[0];
		let onset: number | null = null, peak: number | null = null, down: number | null = null;
		if (main?.points.length) {
			const pts = main.points, top = Math.max(...pts.map((p) => p.y));
			const pk = pts.find((p) => p.y === top)!;
			onset = pts.find((p) => p.y >= 0.15 * top)?.x ?? null;
			peak = pk.x;
			down = pts.find((p) => p.x > pk.x && p.y <= 0.5 * top)?.x ?? null;
		}
		const felt = obs.find((o) => N(o.hrs) > t0 && L(o.effects).length > 0);
		if (felt) onset = N(felt.hrs);
		const near = (x: number | null) => {
			if (x == null) return null;
			const m = core.reduce((a, b) => (Math.abs(b.t - x) < Math.abs(a.t - x) ? b : a));
			return Math.abs(m.t - x) <= Math.max(0.5, x * 0.35) ? m : null;
		};
		const out: Milestone[] = [];
		const last = core[core.length - 1];
		const downM = near(down);
		for (const [label, m] of [['Kicking in', near(onset)], ['Peak', near(peak)], ['Coming down', downM === last ? core[core.length - 2] : downM], ['Last effects', last]] as [string, Mark | null][]) {
			const prev = out[out.length - 1];
			if (!m || (prev && m.t <= prev.t)) continue;
			const lineStart = body.lastIndexOf('\n', m.start - 1) + 1;
			const at = m.start - lineStart <= 60 && !marks.some((o) => o.start >= lineStart && o.start < m.start) ? lineStart : m.start;
			out.push({ label, t: m.t, at });
		}
		return out;
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [byTime, coreEnd, expected, obsQ.data, body]);

	const [t, setT] = useState(0);
	const [playing, setPlaying] = useState(false);
	const [speed, setSpeed] = useState(1);
	const [hoverEffect, setHoverEffect] = useState<string | null>(null);
	const [atLink, setAtLink] = useDiveState<number | null>('at', null);
	const [copied, setCopied] = useState(false);
	const [dockOpen, setDockOpen] = useState(() => typeof window !== 'undefined' && !!window.matchMedia?.('(min-width: 961px)').matches);
	const [allNames, setAllNames] = useState(false);
	const wide = useWide();
	const { effectInfo, open, classOf } = useContext(OpenCtx);
	const takenRef = useRef<HTMLOListElement | null>(null);
	const bodyRef = useRef<HTMLDivElement | null>(null);
	const holdUntil = useRef(0);
	const follow = useRef(false);
	const autoScroll = useRef(0); // until when scroll events are our own
	const frozenRef = useRef(frozen);
	frozenRef.current = frozen;

	useEffect(() => {
		setT(atLink ?? 0);
		setPlaying(false);
		setShowAll(false);
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [id]);
	useEffect(() => {
		if (!playing) setAtLink(Math.round(t * 100) / 100);
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [playing, t]);

	const activeIdx = useMemo(() => {
		let idx = -1;
		byTime.forEach((m, i) => {
			if (m.t <= t + 1e-9) idx = i;
		});
		return idx;
	}, [byTime, t]);
	const active = activeIdx >= 0 ? byTime[activeIdx] : null;

	const lastIdx = useRef(-1);
	useEffect(() => {
		if (playing && activeIdx !== lastIdx.current && activeIdx >= 0) holdUntil.current = Math.max(holdUntil.current, Date.now() + DWELL_MS);
		lastIdx.current = activeIdx;
	}, [activeIdx, playing]);

	// Whenever the big "moment" text changes while playing, hold long enough to read it (~200 wpm, 3–12 s).
	const heroObs = useMemo(() => [...obs].reverse().find((o) => N(o.hrs) <= t + 1e-9) ?? null, [obsQ.data, t]);
	const heroKey = heroObs ? `o${S(heroObs.obs_index)}` : `m${active?.start ?? 'start'}`;
	const heroWords = (heroObs ? S(heroObs.description) : active ? body.slice(Math.max(0, active.start - 100), active.end + 220) : '').split(/\s+/).filter(Boolean).length;
	const [hold, setHold] = useState<{ key: string; ms: number } | null>(null);
	const lastHero = useRef('');
	useEffect(() => {
		if (heroKey === lastHero.current) return;
		lastHero.current = heroKey;
		if (!playing || heroKey === 'mstart') return;
		const ms = clamp(1500 + heroWords * 300, 3000, 12000) / Math.sqrt(speed);
		holdUntil.current = Math.max(holdUntil.current, Date.now() + ms);
		setHold({ key: heroKey, ms });
	}, [heroKey, playing]);
	const takenCount = doses.filter((d) => d.t <= t + 1e-9).length;
	useEffect(() => {
		const list = takenRef.current;
		const items = list ? list.querySelectorAll<HTMLElement>('[data-taken="1"]') : null;
		const last = items && items[items.length - 1];
		if (list && last) list.scrollTo({ top: last.offsetTop - list.clientHeight / 2, behavior: 'smooth' });
	}, [takenCount]);
	// A short beat whenever a new dose is taken.
	const dosesTaken = doses.filter((d) => d.t <= t + 1e-9).length;
	const lastDoses = useRef(0);
	useEffect(() => {
		if (playing && dosesTaken > lastDoses.current) holdUntil.current = Math.max(holdUntil.current, Date.now() + 1800 / Math.sqrt(speed));
		lastDoses.current = dosesTaken;
	}, [dosesTaken, playing]);
	// The turning point we're in; a longer beat when playback reaches a new one.
	const msIdx = milestones.reduce((k, m, i) => (m.t <= t + 1e-9 ? i : k), -1);
	const phase = msIdx >= 0 ? milestones[msIdx] : null;
	const lastMs = useRef(-1);
	useEffect(() => {
		if (playing && msIdx > lastMs.current) holdUntil.current = Math.max(holdUntil.current, Date.now() + 2400 / Math.sqrt(speed));
		lastMs.current = msIdx;
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [msIdx, playing]);

	useEffect(() => {
		if (!playing) return;
		const tick = 50;
		const timer = setInterval(() => {
			if (frozenRef.current || Date.now() < holdUntil.current) return;
			setT((prev) => {
				const next = prev + (tick / HOUR_MS_AT_1X) * speed;
				if (next >= maxT) {
					setPlaying(false);
					return maxT;
				}
				return next;
			});
		}, tick);
		return () => clearInterval(timer);
	}, [playing, speed, maxT]);

	useEffect(() => {
		if (!active || !bodyRef.current) return;
		const box = bodyRef.current;
		const el = box.querySelector(`[data-start="${active.start}"]`) as HTMLElement | null;
		if (el && (playing || follow.current)) {
			autoScroll.current = Date.now() + 900;
			el.scrollIntoView({ block: 'center', behavior: 'smooth' });
		}
		follow.current = false;
	}, [active?.start]);

	// Reading moves the timeline: while not playing, the moment is the last time mark above the reading line.
	// Scrolls we cause ourselves (following playback or a jump) are ignored.
	useEffect(() => {
		let raf = 0;
		const onScroll = () => {
			if (raf) return;
			raf = requestAnimationFrame(() => {
				raf = 0;
				if (playing || Date.now() < autoScroll.current || !bodyRef.current) return;
				const line = window.innerHeight * 0.45;
				let best: { top: number; t: number } | null = null;
				for (const el of bodyRef.current.querySelectorAll<HTMLElement>('[data-t]')) {
					const top = el.getBoundingClientRect().top;
					if (top <= line && (!best || top > best.top)) best = { top, t: Number(el.dataset.t) };
				}
				const next = best ? best.t : 0;
				setT((prev) => (Math.abs(prev - next) > 1e-6 ? next : prev));
			});
		};
		window.addEventListener('scroll', onScroll, { passive: true });
		return () => {
			window.removeEventListener('scroll', onScroll);
			cancelAnimationFrame(raf);
		};
	}, [playing]);

	const segments = useMemo(() => {
		const parts: { text: string; from: number; mark?: Mark; ms?: number }[] = [];
		const cuts = [...milestones.map((ms, i) => ({ pos: ms.at, ms: i, mark: undefined })), ...marks.map((m) => ({ pos: m.start, ms: undefined, mark: m }))].sort((a, b) => a.pos - b.pos);
		let pos = 0;
		for (const c of cuts) {
			if (c.pos > pos) parts.push({ text: body.slice(pos, c.pos), from: pos });
			pos = Math.max(pos, c.pos);
			if (c.mark) {
				parts.push({ text: body.slice(c.mark.start, c.mark.end), from: c.mark.start, mark: c.mark });
				pos = c.mark.end;
			} else parts.push({ text: '', from: c.pos, ms: c.ms });
		}
		if (pos < body.length) parts.push({ text: body.slice(pos), from: pos });
		return parts;
	}, [body, marks, milestones]);

	if (reportQ.isLoading || marksQ.isLoading || obsQ.isLoading) return <div className="rd-card animate-pulse" style={{ height: 420 }} />;
	if (!report) return <p style={{ color: C.soft }}>Report not found.</p>;

	const jump = (to: number) => {
		follow.current = true;
		setPlaying(false);
		setT(clamp(to, 0, maxT));
	};
	const nextMark = () => jump((byTime.find((m) => m.t > t + 1e-6) ?? { t: maxT }).t);
	const prevMark = () => jump(([...byTime].reverse().find((m) => m.t < t - 1e-6) ?? { t: 0 }).t);

	const takenSoFar = doses.filter((d) => d.t <= t + 1e-9).sort((a, b) => a.t - b.t);
	const nowObs = [...obs].reverse().find((o) => N(o.hrs) <= t + 1e-9) ?? null;
	const momentObs = nowObs ?? obs.find((o) => N(o.hrs) > t && N(o.hrs) - t <= 0.5) ?? null;
	const nowMood = momentObs ? MOMENT[S(momentObs.sentiment)] ?? MOMENT.neutral : null;
	const overall = report ? MOMENT[S(report.overall)] : undefined;
	const hiRules = rulesFor(momentObs ? L(momentObs.effects) : [], (e) => effectTone(effectInfo.get(e.toLowerCase())));
	const passage = active ? { from: active.end, to: marks.find((m) => m.start > active.start)?.start ?? body.length } : null;
	const renderPlain = (text: string, from: number, key: string) => {
		if (!passage || from + text.length <= passage.from || from >= passage.to) return text;
		const a = Math.max(0, passage.from - from), b = Math.min(text.length, passage.to - from);
		return (
			<>
				{text.slice(0, a)}
				<span style={{ background: PASSAGE_BG, borderRadius: 4, boxDecorationBreak: 'clone', WebkitBoxDecorationBreak: 'clone', color: C.text, transition: 'background .4s' }}>
					{markWords(text.slice(a, b), hiRules, hoverEffect, key)}
				</span>
				{text.slice(b)}
			</>
		);
	};
	// Without a close reading, show what the report says right after the active mark, up to the next one.
	const quote = (() => {
		if (!active) return '';
		const next = marks.find((m) => m.start > active.start);
		let text = body.slice(active.end, next ? next.start : body.length);
		text = text.replace(/^[\s\]\)\-–—:,.]*(\[[^\]]*\])?[\s\]\)\-–—:,.]*/, '').replace(/\s+/g, ' ').trim();
		if (text.length < 25) {
			const lineStart = Math.max(body.lastIndexOf('\n', active.start) + 1, 0);
			text = body.slice(lineStart, lineStart + 400).replace(/\s+/g, ' ').trim();
		}
		if (text.length > 360) {
			const cut = text.slice(0, 360);
			const end = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
			text = end > 120 ? cut.slice(0, end + 1) : cut.replace(/\s+\S*$/, '') + '…';
		}
		return text;
	})();

	const moodPts = obs.length >= 2
		? obs.map((o) => ({ x: N(o.hrs), y: (MOMENT[S(o.sentiment)] ?? MOMENT.neutral).y }))
		: byTime.filter((m) => m.valence != null).map((m) => ({ x: m.t, y: m.valence as number }));
	const lanes: Lane[] = [];
	if (moodPts.length >= 4) lanes.push({ label: 'Mood', height: 84, min: -1.1, max: 1.1, diverging: true, linear: true, series: [{ key: 'mood', label: 'Mood', color: C.lav, points: moodPts }] });
	for (const x of expected.series) lanes.push({ label: short(x.label), sub: x.sub, color: x.color, height: 50, marks: doses.filter((d) => d.sub === x.label).map((d) => d.t), min: 0, max: Math.max(1.1, ...x.points.map((p) => p.y)) * 1.1, series: [x] });
	const hourStep = maxT <= 2 ? 0.25 : maxT <= 6 ? 1 : maxT <= 14 ? 2 : 4;
	const xLabels = Array.from({ length: Math.floor(maxT / hourStep) + 1 }, (_, i) => ({ x: i * hourStep, label: fmtT(i * hourStep) }));

	// Active now: inside its expected effect curve, or (no timing data) taken within the last 6 h.
	const activeSubs = [...new Set(takenSoFar.map((d) => d.sub))].filter((sub) => {
		const ser = expected.series.find((x) => x.label === sub);
		if (ser) return ser.points.length > 0 && t >= ser.points[0].x && t <= ser.points[ser.points.length - 1].x && (interp(ser.points, t) ?? 0) > 0.05;
		return takenSoFar.some((d) => d.sub === sub && t - d.t <= 6);
	});
	const activeNotes = activeSubs.length < 2 ? [] : rows(pairsQ).filter((p) => activeSubs.includes(S(p.a)) && activeSubs.includes(S(p.b)));
	const riskNow = Math.max(0, ...activeNotes.map((p) => N(p.sev)));
	const mixing = (() => {
							if (activeSubs.length < 2) return null;
							const notes = activeNotes;
							const flagged = notes.filter((p) => p.sev != null).sort((a, b) => N(b.sev) - N(a.sev));
							const low = notes.filter((p) => p.sev == null && p.status);
							const pwPage = (p: Record<string, unknown>) => {
								// The flag sits on the page of the substance whose interaction list names the other one.
								const via = S(p.via).toLowerCase();
								const page = [S(p.a), S(p.b)].find((n) => !via.includes(n.toLowerCase())) ?? S(p.a);
								return `https://psychonautwiki.org/wiki/${encodeURIComponent(page.replace(/ /g, '_'))}#Dangerous_interactions`;
							};
							return (
								<div>
									<div className="flex flex-wrap items-center gap-2">
										<span className="rd-label pr-1">Mixing now</span>
										<span className="text-sm" style={{ color: C.soft }}>
											{activeSubs.map(short).join(' + ')}
											{!notes.length && <span style={{ color: C.faint }}> · no note on file, which isn't the same as safe</span>}
										</span>
									</div>
									{notes.length > 0 && <MixNotes items={[...flagged, ...low]} pwPage={pwPage} />}
									{notes.some((p) => S(p.via) === 'TripSit') && (
										<div className="mt-3">
											<TripSitBadge />
										</div>
									)}
								</div>
							);
						})();
	const moodScale = obs.length >= 2 ? 1 : 3;
	const moodLine = moodPts.map((p) => ({ x: p.x, y: clamp(p.y * moodScale, -1, 1) }));
	const moodNow = momentObs ? (MOMENT[S(momentObs.sentiment)] ?? MOMENT.neutral).y : clamp((interp(moodPts, t) ?? 0) * moodScale, -1, 1);

	// The timeline: a card at the top of the side column on wide screens, a floating dock at the bottom on phones.
	const timeline = (side: boolean) => (
		<div
			className={side ? 'rd-card p-4' : 'rd-dock'}
			style={{ borderColor: `${moodColor(moodNow)}55`, boxShadow: side ? undefined : `0 10px 40px rgba(10,4,40,.35), 0 0 0 1px ${moodColor(moodNow)}22`, transition: 'border-color 1.2s ease' }}
		>
			<div className="flex items-center gap-3">
				<button onClick={prevMark} className="rd-btn rd-hide-sm" aria-label="Previous mark" style={{ padding: 7, background: 'transparent', border: 0 }}>
					<SkipBack size={15} />
				</button>
				<button
					onClick={() => {
						if (t >= maxT) setT(0);
						setPlaying(!playing);
					}}
					aria-label={playing ? 'Pause' : 'Play'}
					className="flex items-center justify-center"
					style={{ width: 40, height: 40, borderRadius: '50%', background: '#fff', color: C.deep, flexShrink: 0, boxShadow: playing ? `0 0 0 5px ${moodColor(moodNow)}33` : 'none', transition: 'box-shadow .4s' }}
				>
					{playing ? <Pause size={16} /> : <Play size={16} style={{ marginLeft: 2 }} />}
				</button>
				<button onClick={nextMark} className="rd-btn rd-hide-sm" aria-label="Next mark" style={{ padding: 7, background: 'transparent', border: 0 }}>
					<SkipForward size={15} />
				</button>
				<div className="text-xl font-light tabular-nums" style={{ minWidth: 56, letterSpacing: '-0.02em' }}>{fmtT(t)}</div>
				<div className="flex-1" style={{ minWidth: 0 }}>
					{dockOpen || side ? (
						<span className="block truncate text-sm font-semibold" style={{ color: phase ? '#fff' : C.faint }}>
							{phase?.label ?? ''}
						</span>
					) : (
						<MiniTimeline
							xMax={maxT}
							x={t}
							onScrub={jump}
							mood={moodLine}
							drugs={expected.series}
							ticks={byTime.map((m, i) => ({ x: m.t, on: m.t <= t + 1e-9, active: i === activeIdx }))}
							flags={milestones.map((m, i) => ({ x: m.t, label: m.label, on: i <= msIdx }))}
						/>
					)}
				</div>
				<select value={speed} onChange={(e) => setSpeed(Number(e.target.value))} className="rd-btn" style={{ padding: '3px 6px', fontSize: 12, background: 'transparent' }} aria-label="Speed">
					{[0.5, 1, 2, 4].map((v) => (
						<option key={v} value={v} style={{ color: '#000' }}>
							{v}×
						</option>
					))}
				</select>
				<button className="rd-btn" aria-label={dockOpen ? 'Hide details' : 'Show details'} title={dockOpen ? 'Hide details' : 'Show mood and drug lanes'} style={{ padding: 6, background: 'transparent' }} onClick={() => setDockOpen(!dockOpen)}>
					{dockOpen === !side ? <ChevronDown size={15} /> : <ChevronUp size={15} />}
				</button>
			</div>
			{side && !dockOpen && (
				<div className="mt-3">
					<MiniTimeline
						xMax={maxT}
						x={t}
						onScrub={jump}
						mood={moodLine}
						drugs={expected.series}
						ticks={byTime.map((m, i) => ({ x: m.t, on: m.t <= t + 1e-9, active: i === activeIdx }))}
						flags={milestones.map((m, i) => ({ x: m.t, label: m.label, on: i <= msIdx }))}
					/>
				</div>
			)}
			{dockOpen && (
				<div className="rd-fade mt-3 border-t pt-3" style={{ borderColor: C.line, maxHeight: side ? 'none' : '38vh', overflowY: 'auto', scrollbarWidth: 'none' }}>
					{lanes.length > 0 && (
						<ScrubChart
							id="rep"
							lanes={lanes.map((l) => ({ ...l, height: l.diverging ? 56 : 34 }))}
							xMax={maxT}
							x={t}
							onScrub={jump}
							ticks={byTime.map((m, i) => ({ x: m.t, on: m.t <= t + 1e-9, active: i === activeIdx }))}
							xLabels={xLabels}
							cursorLabel={fmtT(t)}
						/>
					)}
					{coreEnd != null && (
						<button className="rd-btn mt-2" style={{ padding: '3px 10px', fontSize: 12 }} onClick={() => setShowAll(!showAll)}>
							{showAll ? 'Focus on the main part' : `Show all ${fmtT(fullT)}`}
						</button>
					)}
				</div>
			)}
		</div>
	);

	return (
		<section className="rd-fade" style={{ position: 'relative', zIndex: 0, paddingBottom: wide ? 0 : dockOpen ? 340 : 120 }}>
			<header>
				{(() => {
					const taken = [...new Set([...doses].sort((a, b) => a.t - b.t).map((d) => d.sub))];
					const names = taken.length ? taken : S(report.subs).split(' · ').filter(Boolean);
					const overallWord = { positive: 'went well', negative: 'was rough', mixed: 'was mixed', neutral: 'was neutral' }[S(report.overall)];
					return (
						<>
							<div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3">
								<h1 className="flex flex-wrap items-center gap-x-4 gap-y-1 text-3xl font-semibold" style={{ letterSpacing: '-0.02em' }}>
									{(allNames ? names : names.slice(0, 4)).map((n) => (
										<button key={n} onClick={() => open({ kind: 'substance', name: n })} className="inline-flex items-center gap-2" style={{ whiteSpace: 'nowrap', textDecoration: 'underline', textDecorationColor: 'rgba(255,255,255,.25)', textDecorationThickness: 1, textUnderlineOffset: 6 }} title={`About ${n}`}>
											<SubstanceIcon name={n} />
											{short(n)}
										</button>
									))}
									{names.length > 4 && (
										<button className="rd-btn" style={{ fontSize: 14, padding: '5px 12px', alignSelf: 'center' }} onClick={() => setAllNames(!allNames)} title={allNames ? 'Show fewer' : names.slice(4).join(', ')}>
											{allNames ? 'Show fewer' : `+${names.length - 4} more`}
										</button>
									)}
								</h1>
								<div className="flex items-center gap-2">
									<a
										href={`https://erowid.org/experiences/exp.php?ID=${id.replace('erowid-', '')}`}
										target="_blank"
										rel="noopener noreferrer"
										className="rd-tag"
										title="Read the original report on Erowid"
										style={{ textDecoration: 'none', background: 'rgba(255,255,255,.08)' }}
									>
										<img src={EROWID_ICON} alt="" width={16} height={16} style={{ display: 'block', borderRadius: 4 }} />
										Erowid #{id.replace('erowid-', '')}
										<span style={{ color: C.faint }}>↗</span>
									</a>
									<button
										className="rd-tag"
										aria-label="Copy link to this moment"
										title={copied ? 'Link copied' : 'Copy link to this moment'}
										style={{ background: copied ? 'rgba(166,242,228,.18)' : 'rgba(255,255,255,.08)', padding: '6px 10px' }}
										onClick={() => {
											navigator.clipboard?.writeText(window.location.href).then(() => {
												setCopied(true);
												setTimeout(() => setCopied(false), 1500);
											});
										}}
									>
										{copied ? <Check size={14} color={C.mint} /> : <Link2 size={14} />}
									</button>
								</div>
							</div>
							<p className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 text-sm" style={{ color: C.faint }}>
									{report.yr != null && (
										<span className="inline-flex items-center gap-1.5" title="Year of the experience">
											<Calendar size={13} /> {N(report.yr)}
										</span>
									)}
									{(S(report.gender) || report.age != null) && (
										<span className="inline-flex items-center gap-1.5" title="Who wrote it">
											<User size={13} /> {[S(report.gender), report.age != null ? String(N(report.age)) : ''].filter(Boolean).join(', ')}
										</span>
									)}
									<span className="inline-flex items-center gap-1.5" title="How long the story covers">
										<Clock size={13} /> {fmtDur(storyEnd)}
									</span>
									{overall && overallWord && (
										<span className="inline-flex items-center gap-1.5" style={{ color: overall.color }} title="How it went overall">
											<span className="rd-dot" style={{ background: overall.color }} /> {overallWord}
										</span>
									)}
									{report.repeat != null && (
										<span className="inline-flex items-center gap-1.5" title="Would they do it again?">
											<RotateCcw size={13} /> {report.repeat ? 'would do it again' : 'wouldn' + "'" + 't do it again'}
										</span>
									)}
								</p>
								{allEffects.length > 0 && (
									<div className="mt-5 flex flex-wrap items-center gap-2">
										<span className="rd-label mr-1">What happened</span>
										{(allTags ? allEffects : allEffects.slice(0, 12)).map(([e, v]) => (
											<span key={e} style={{ opacity: v.first <= t + 1e-9 ? 1 : 0.4, transition: 'opacity .6s' }} title={`First at ${fmtT(v.first)} · mentioned ${v.n}×`}>
												<EffectTag name={e} />
											</span>
										))}
										{allEffects.length > 12 && (
											<button className="text-sm" style={{ color: C.faint }} onClick={() => setAllTags(!allTags)}>
												{allTags ? 'Show fewer' : `+${allEffects.length - 12} more`}
											</button>
										)}
									</div>
								)}
						</>
					);
				})()}
			</header>

			{/* Mood tint: the page leans mint when it's going well, pink when it's rough */}
			<div aria-hidden className="rd-tint" style={{ background: 'radial-gradient(1200px 520px at 50% -8%, rgba(140,236,214,.30), transparent 70%), radial-gradient(1000px 480px at 50% 108%, rgba(140,236,214,.22), transparent 70%)', opacity: clamp(moodNow, 0, 1) * 0.9 }} />
			<div aria-hidden className="rd-tint" style={{ background: 'radial-gradient(1200px 520px at 50% -8%, rgba(255,150,180,.32), transparent 70%), radial-gradient(1000px 480px at 50% 108%, rgba(255,150,180,.24), transparent 70%)', opacity: clamp(-moodNow, 0, 1) * 0.9 }} />
			{[2, 3].map((r) => (
				<div key={r} aria-hidden className="rd-tint" style={{ background: RISK_TINT[r], opacity: riskNow === r ? 1 : 0 }} />
			))}
			{!wide && <div aria-hidden className="rd-fadebar" />}

			<div className="rd-tl mt-8">
				{/* The story: the main column */}
				<article ref={bodyRef} className={`rd-story ${active && playing ? 'focus' : ''}`}>
					{segments.map((s, i) =>
						s.ms != null ? (
							<span key={i} role="button" tabIndex={0} className={`rd-ms ${s.ms === msIdx ? 'now' : s.ms < msIdx ? 'past' : 'future'}`} onClick={() => jump(milestones[s.ms!].t)} onKeyDown={(e) => e.key === 'Enter' && jump(milestones[s.ms!].t)}>
								<span className="rd-ms-line" />
								<span className="rd-ms-pill">
									{milestones[s.ms].label}
									<span className="rd-ms-t">{fmtT(milestones[s.ms].t)}</span>
								</span>
								<span className="rd-ms-line" />
							</span>
						) : s.mark ? (
							<Fragment key={i}>
								<span data-start={s.mark.start} data-t={s.mark.t} className={`rd-mark ${s.text ? '' : 'stamp'} ${active && s.mark.start === active.start ? 'active' : s.mark.t <= t + 1e-9 ? 'past' : 'future'}`} onClick={() => jump(s.mark!.t)} title={fmtT(s.mark.t)}>
									{s.text || fmtT(s.mark.t)}
								</span>
								{s.mark.method === 'obs' && s.mark.t <= t + 1e-9 && newEffects.get(s.mark.raw)?.slice(0, 3).map((e) => (
									<button key={e} className="rd-eff rd-in" onClick={() => open({ kind: 'effect', name: e })} title={`${e} starts here`} style={{ background: HI[effectTone(effectInfo.get(e.toLowerCase()))] }}>
										+ {e}
									</button>
								))}
								{!s.text && ' '}
							</Fragment>
						) : (
							<span key={i}>{renderPlain(s.text, s.from, `b${i}`)}</span>
						),
					)}
					<Sources className="mt-10 border-t pt-5" list={[['erowid', `https://erowid.org/experiences/exp.php?ID=${id.replace('erowid-', '')}`], 'sei', 'pw', ...(rows(pairsQ).length ? ['tripsit' as const] : [])]} />
				</article>

				{/* Alongside the story: the moment, and the doses */}
				<aside className="rd-side">
					{mixing && <div className="rd-card rd-in p-4">{mixing}</div>}
					{wide && timeline(true)}
					<div key={heroKey} className="rd-in px-1 pb-2 pt-3">
						<div className="flex flex-wrap items-center gap-3">
							<span className="rd-label">
								{phase && <span style={{ color: '#fff' }}>{phase.label} · </span>}
								{phase ? '' : 'At '}
								{fmtT(t)}
							</span>
							{nowMood && (
								<span className="inline-flex items-center gap-2 text-sm font-semibold" style={{ color: nowMood.color }}>
									<span className="rd-dot" style={{ width: 8, height: 8, background: nowMood.color }} />
									{nowMood.label}
								</span>
							)}
						</div>
						{(momentObs || quote) && (
							<span aria-hidden style={{ display: 'block', fontFamily: SERIF, fontSize: 64, lineHeight: 1, height: 30, marginTop: 10, color: nowMood?.color ?? C.lav, opacity: 0.8, transition: 'color .6s' }}>
								“
							</span>
						)}
						{momentObs ? (
							<p style={{ fontFamily: SERIF, fontSize: 21, lineHeight: 1.5, color: C.text }}>
								{markWords(S(momentObs.description), hiRules, hoverEffect, 'd')}
							</p>
						) : quote ? (
							<p style={{ fontFamily: SERIF, fontSize: 19, lineHeight: 1.5, color: C.text }}>
								{markWords(quote, hiRules, hoverEffect, 'q')}
							</p>
						) : (
							<p className="mt-3 text-sm" style={{ color: C.faint }}>Press play, or drag the timeline, to step through the story.</p>
						)}
						{momentObs && L(momentObs.effects).length > 0 && (
							<div className="mt-4 flex flex-wrap gap-2">
								{L(momentObs.effects).map((e) => (
									<span key={e} onMouseEnter={() => setHoverEffect(e)} onMouseLeave={() => setHoverEffect(null)} onFocus={() => setHoverEffect(e)} onBlur={() => setHoverEffect(null)} style={{ borderBottom: `2px solid ${HI[effectTone(effectInfo.get(e.toLowerCase()))]}`, borderRadius: 999, paddingBottom: 2 }}>
										<EffectTag name={e} />
									</span>
								))}
							</div>
						)}
						{playing && hold && hold.key === heroKey && (
							<div className="mt-5" style={{ height: 2, background: 'rgba(255,255,255,.1)', borderRadius: 2, overflow: 'hidden' }} aria-hidden>
								<div key={hold.key} style={{ height: 2, background: C.lav, animation: `rd-fill ${hold.ms}ms linear both` }} />
							</div>
						)}
					</div>

					<div className="rd-card p-4">
						<div className="flex items-baseline justify-between">
							<span className="rd-label">Doses</span>
							<span className="text-xs" style={{ color: C.faint }}>
								{takenSoFar.length} of {doses.length} taken · tap to jump
							</span>
						</div>
						{doses.length === 0 ? (
							<div className="mt-2 text-sm" style={{ color: C.faint }}>No doses recorded.</div>
						) : (
							<ol ref={takenRef} className="mt-2 grid gap-0.5" style={{ maxHeight: 230, overflowY: 'auto', scrollbarWidth: 'none' }}>
								{[...doses].sort((p, q) => p.t - q.t).map((d, i, all) => {
									const taken = d.t <= t + 1e-9;
									const latest = taken && i === takenSoFar.length - 1;
									// Taken a while after something it shares tolerance with: it may land softer.
									const earlier = d.assumed ? undefined : all.find((e) => !e.assumed && e.sub !== d.sub && e.t < d.t - 0.25 && sharesTol(rows(tolQ), e.sub, d.sub));
									return (
										<li
											key={i}
											data-taken={taken ? '1' : '0'}
											role="button"
											tabIndex={0}
											onClick={() => jump(d.t)}
											onKeyDown={(e) => e.key === 'Enter' && jump(d.t)}
											className={`rd-hover rd-dose cursor-pointer rounded-lg px-2 py-1.5 text-sm ${latest ? 'rd-new' : ''}`}
											title={d.assumed ? 'Time not given' : `Jump to ${fmtT(d.t)}`}
											style={{ border: '1px solid transparent', opacity: taken ? 1 : 0.45, transition: 'opacity .3s' }}
										>
											<span className="tabular-nums" style={{ color: C.faint, textAlign: 'right' }}>{d.assumed ? '—' : fmtT(d.t)}</span>
											<span className="flex justify-center">
												<ClassIcon cls={classOf(d.sub)} size={14} color={C.coral} />
											</span>
											<button
												onClick={(e) => {
													e.stopPropagation();
													open({ kind: 'substance', name: d.sub });
												}}
												className="font-semibold"
												title={`About ${d.sub}`}
												style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', textAlign: 'left' }}
											>
												{short(d.sub)}
												{earlier && (
													<span title={`Shares tolerance with ${short(earlier.sub)}, taken earlier, so this may feel weaker`} style={{ display: 'inline-flex', marginLeft: 6, verticalAlign: -1, color: C.lav, opacity: 0.8 }}>
														<Repeat size={12} />
													</span>
												)}
											</button>
											<span className="flex justify-center">{d.route && <RouteIcon route={d.route} />}</span>
											<span className="tabular-nums" style={{ color: C.soft, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', textAlign: 'right' }} title={d.amount}>
												{/\d/.test(d.amount) ? d.amount : ''}
											</span>

										</li>
									);
								})}
							</ol>
						)}
					</div>
				</aside>
			</div>

			{!wide && timeline(false)}
			<Err q={marksQ} />
		</section>
	);
}

// ── Spunion ───────────────────────────────────────────────────────
// re:dose's mascot, drawn as SVG so each eye can blink on its own. He bobs gently, blinks one eye at a time
// (the two eyes run on different clocks), and offers a tip for the page in a speech bubble. Tap him for the next
// tip; close the bubble and he stays quietly in the corner.

const SPUNION_CSS = `
@keyframes sp-bob { 0%, 100% { transform: translateY(0) rotate(-3deg); } 50% { transform: translateY(-5px) rotate(3deg); } }
@keyframes sp-blink { 0%, 93%, 100% { transform: scaleY(1); } 96% { transform: scaleY(.08); } }
@keyframes sp-hop { 0% { transform: translateY(0) scale(1, 1); } 30% { transform: translateY(2px) scale(1.08, .9); } 60% { transform: translateY(-12px) scale(.94, 1.06); } 100% { transform: translateY(0) scale(1, 1); } }
.sp-wrap { position: fixed; right: 18px; bottom: 18px; z-index: 35; display: flex; align-items: flex-end; gap: 10px; pointer-events: none; }
.sp-wrap > * { pointer-events: auto; }
.sp-me { width: 68px; height: 68px; cursor: pointer; filter: drop-shadow(0 8px 18px rgba(10,4,40,.35)); background: none; border: 0; padding: 0; }
.sp-me svg { overflow: visible; display: block; }
.sp-body { animation: sp-bob 3.4s ease-in-out infinite; transform-origin: 50% 92%; transform-box: fill-box; }
.sp-me.hop .sp-body { animation: sp-hop .55s ease-out 1, sp-bob 3.4s ease-in-out .55s infinite; }
.sp-eye { animation: sp-blink 4.7s infinite; transform-origin: center; transform-box: fill-box; }
.sp-eye.r { animation-duration: 6.1s; animation-delay: 2.3s; }
.sp-bubble { position: relative; max-width: min(280px, calc(100vw - 110px)); margin-bottom: 30px; padding: 12px 34px 12px 14px; border-radius: 18px 18px 6px 18px;
  background: rgba(40,31,92,.92); border: 1px solid rgba(255,255,255,.18); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 12px 34px rgba(10,4,40,.35); font-size: 14px; line-height: 1.45; color: #fff; }
.sp-bubble b { color: #8ff4c8; }
@media (max-width: 960px) { .sp-wrap.lift { bottom: 104px; } .sp-me { width: 54px; height: 54px; } }
@media (prefers-reduced-motion: reduce) { .sp-body, .sp-eye, .sp-me.hop .sp-body { animation: none !important; } }
`;

function SpunionSvg() {
	return (
		<svg viewBox="0 0 500 500" width="100%" height="100%" aria-hidden>
			<g className="sp-body">
				<path
					d="M70 190 C110 112 196 62 288 32 C316 23 330 46 302 57 C284 64 268 70 271 78 C275 87 302 82 332 96 C424 138 472 222 466 312 C460 412 380 472 263 471 C138 470 38 400 38 300 C38 256 50 222 70 190 Z"
					fill="#7ffcc4"
					stroke="#000"
					strokeWidth="18"
					strokeLinejoin="round"
				/>
				{/* blush */}
				<ellipse cx="120" cy="392" rx="30" ry="15" fill="#ff5c93" opacity="0.6" />
				<ellipse cx="405" cy="350" rx="24" ry="12" fill="#ff5c93" opacity="0.6" />
				{/* left eye */}
				<g className="sp-eye">
					<circle cx="185" cy="300" r="86" fill="#000" />
					<circle cx="185" cy="300" r="70" fill="none" stroke="#fff" strokeWidth="5" />
					<circle cx="160" cy="272" r="17" fill="#fff" />
					<circle cx="205" cy="322" r="7" fill="#fff" />
				</g>
				{/* right eye */}
				<g className="sp-eye r">
					<circle cx="357" cy="268" r="64" fill="#000" />
					<circle cx="357" cy="268" r="49" fill="none" stroke="#fff" strokeWidth="5" />
					<circle cx="339" cy="248" r="12" fill="#fff" />
					<circle cx="372" cy="284" r="5" fill="#fff" />
				</g>
			</g>
		</svg>
	);
}

function Spunion({ tips, lift }: { tips: string[]; lift: boolean }) {
	const [i, setI] = useState(0);
	const [open, setOpen] = useState(true);
	const [hop, setHop] = useState(false);
	const key = tips.join('|');
	useEffect(() => setI(0), [key]);
	if (!tips.length) return null;
	const tip = tips[i % tips.length];
	const next = () => {
		setHop(true);
		setTimeout(() => setHop(false), 560);
		if (open) setI(i + 1);
		setOpen(true);
	};
	return (
		<div className={`sp-wrap ${lift ? 'lift' : ''}`}>
			<style>{SPUNION_CSS}</style>
			{open && (
				<div key={tip} className="sp-bubble rd-in" role="status">
					{tip}
					<button onClick={() => setOpen(false)} aria-label="Hide tip" style={{ position: 'absolute', top: 9, right: 9, color: 'rgba(255,255,255,.6)' }}>
						<X size={14} />
					</button>
				</div>
			)}
			<button className={`sp-me ${hop ? 'hop' : ''}`} onClick={next} aria-label={open ? 'Spunion: next tip' : 'Spunion: show a tip'} title="Spunion">
				<SpunionSvg />
			</button>
		</div>
	);
}

// General harm-reduction tips Spunion cycles through after the page's own.
const SPUNION_TIPS = [
	'Start low and go slow, especially with something new.',
	'Most of the risk is in mixing. Check a combination before you try it.',
	'Testing kits can tell you what’s really in your stuff.',
	'Effects can take a while. Waiting before taking more is never wrong.',
	'Rough time? You’re not alone. The re:dose community is on Discord.',
];

// A faint field of molecules behind everything: hexagon rings, bonds and atoms, drifting very slowly.
const MOLECULE_SVG = `<svg xmlns='http://www.w3.org/2000/svg' width='260' height='260' viewBox='0 0 260 260' fill='none' stroke='white' stroke-width='1.3'>
<path d='M70 54 L92.5 67 L92.5 93 L70 106 L47.5 93 L47.5 67 Z'/><path d='M74 62 L88 70 M88 90 L74 98'/>
<path d='M92.5 67 L130 48 L165 70 L165 110'/><path d='M161 74 L161 106'/>
<path d='M190 163 L209 174 L209 196 L190 207 L171 196 L171 174 Z'/><path d='M171 196 L140 215 M190 163 L190 135'/>
<circle cx='190' cy='130' r='5'/>
<g fill='white' stroke='none'><circle cx='70' cy='54' r='3'/><circle cx='92.5' cy='67' r='3'/><circle cx='92.5' cy='93' r='3'/><circle cx='70' cy='106' r='3'/>
<circle cx='47.5' cy='93' r='3'/><circle cx='47.5' cy='67' r='3'/><circle cx='130' cy='48' r='3.5'/><circle cx='165' cy='70' r='3'/><circle cx='165' cy='110' r='3.5'/>
<circle cx='209' cy='174' r='3'/><circle cx='209' cy='196' r='3'/><circle cx='190' cy='207' r='3'/><circle cx='171' cy='196' r='3'/><circle cx='171' cy='174' r='3'/>
<circle cx='190' cy='163' r='3'/><circle cx='140' cy='215' r='3.5'/><circle cx='28' cy='200' r='2'/><circle cx='238' cy='36' r='2'/><circle cx='118' cy='158' r='1.6'/></g></svg>`;
const MOLECULES = `url("data:image/svg+xml,${encodeURIComponent(MOLECULE_SVG)}")`;

// ── Main ──────────────────────────────────────────────────────────

type Q = ReturnType<typeof useSQLQuery>;

export default function ReportTimelapse() {
	const [view, setView] = useDiveState<'reports' | 'substances' | 'effects'>('view', 'reports');
	const [sub, setSub] = useDiveState<string | null>('substance', null);
	const [reportId, setReportId] = useDiveState<string | null>('report', null);
	const [withSub, setWithSub] = useDiveState<string | null>('with', null);
	const [only, setOnly] = useDiveState<boolean>('only', false);
	const [openItem, setOpenItemState] = useDiveState<Open>('open', null);
	const setOpenItem = (o: Open) => setOpenItemState((o ?? undefined) as Open);
	const [, setAtLink] = useDiveState<number | null>('at', null);

	const pickQ = useSQLQuery(pickListSQL);
	const effectInfoQ = useSQLQuery(effectInfoSQL);
	const effectToneQ = useSQLQuery(effectToneSQL);
	const classesQ = useSQLQuery(classesSQL);
	const classMap = useMemo(() => new Map(rows(classesQ).map((r) => [S(r.name), r.cls == null ? undefined : S(r.cls)])), [classesQ.data]);
	const effectInfo = useMemo(() => {
		const m = new Map<string, EffectInfo>(rows(effectInfoQ).map((r) => [S(r.k), { blurb: S(r.blurb), url: S(r.url) }]));
		for (const r of rows(effectToneQ)) m.set(S(r.k), { ...(m.get(S(r.k)) ?? { blurb: '', url: '' }), neg: N(r.neg), pos: N(r.pos) });
		return m;
	}, [effectInfoQ.data, effectToneQ.data]);

	const onSub = view === 'reports' && !!sub && !reportId;
	const onReport = view === 'reports' && !!reportId;
	const listQ = useSQLQuery(reportListSQL(sub ?? '', withSub, only), { enabled: onSub });
	const comboPairQ = useSQLQuery(reportPairsSQL([sub ?? '', withSub ?? '']), { enabled: onSub && !!withSub });
	const kpiQ = useSQLQuery(kpiSQL(sub ?? '', false), { enabled: onSub });
	const kp = rows(kpiQ)[0];
	// Show each substance on its own clock: a bit past when most people's last effects are noted.
	const horizon = (() => {
		const h = kp && N(kp.n_llm) >= 3 ? Math.max(N(kp.last_h) * 1.6, N(kp.peak_h) * 2.5, 0.4) : 12;
		const nice = [0.25, 0.5, 0.75, 1, 1.5, 2, 3, 4, 6, 8, 10, 12, 16, 24];
		const v = nice.find((x) => x >= h) ?? 24;
		return withSub ? Math.max(v, 6) : v;
	})();
	const curveReady = onSub && !kpiQ.isLoading;
	const curveQ = useSQLQuery(curveSQL(sub ?? '', horizon, withSub, only), { enabled: curveReady });
	const denQ = useSQLQuery(curveDenSQL(sub ?? '', horizon, withSub, only), { enabled: curveReady });
	const pairTimingQ = useSQLQuery(timingSQL(withSub ? [sub ?? '', withSub] : []), { enabled: onSub && !!withSub });
	const pairMoodQ = useSQLQuery(pairMoodSQL(sub ?? '', withSub ?? '', 24), { enabled: onSub && !!withSub });
	const pairSummaryQ = useSQLQuery(pairSummarySQL(sub ?? '', withSub ?? ''), { enabled: onSub && !!withSub });
	const pairEffectsQ = useSQLQuery(pairEffectsSQL(sub ?? '', withSub ?? ''), { enabled: onSub && !!withSub });
	const pairSeqQ = useSQLQuery(pairSeqSQL(sub ?? '', withSub ?? ''), { enabled: onSub && !!withSub });
	const reportQ = useSQLQuery(reportSQL(reportId ?? ''), { enabled: onReport });
	const marksQ = useSQLQuery(reportMarksSQL(reportId ?? ''), { enabled: onReport });
	const dosesQ = useSQLQuery(reportDosesSQL(reportId ?? ''), { enabled: onReport });
	const obsQ = useSQLQuery(reportObsSQL(reportId ?? ''), { enabled: onReport });
	const doseSubs = useMemo(() => [...new Set(rows(dosesQ).map((d) => S(d.sub)).filter(Boolean))].sort(), [dosesQ.data]);
	const timingQ = useSQLQuery(timingSQL(doseSubs), { enabled: onReport && doseSubs.length > 0 });
	const pairsQ = useSQLQuery(reportPairsSQL(doseSubs), { enabled: onReport && doseSubs.length > 1 });
	const effectsQ = useSQLQuery(effectsBrowseSQL, { enabled: view === 'effects' });

	const effectDetailQ = useSQLQuery(effectDetailSQL(openItem?.name ?? ''), { enabled: openItem?.kind === 'effect' });
	const subDetailQ = useSQLQuery(substanceDetailSQL(openItem?.name ?? ''), { enabled: openItem?.kind === 'substance' });
	const subTimingQ = useSQLQuery(timingSQL(openItem?.kind === 'substance' ? [openItem.name] : []), { enabled: openItem?.kind === 'substance' });

	const clearReport = () => setReportId(undefined as unknown as null);
	const goSubstance = (s: string) => {
		setView('reports');
		setSub(s);
		setWithSub(undefined as unknown as null);
		clearReport();
		setOpenItem(null);
	};
	// What Spunion says on this page, before the general tips.
	const spunionTips = (() => {
		const pairSev = withSub ? N(rows(comboPairQ)[0]?.sev) : 0;
		const own =
			onReport ? ['Scroll through the story and the timeline follows along. Or press play and I’ll walk you through it.']
			: onSub && withSub && pairSev >= 2 ? [`${short(sub!)} with ${short(withSub)} is a risky mix. If you go ahead anyway: go low, go slow, and don’t do it alone.`]
			: onSub && withSub ? [`Here’s how ${short(sub!)} and ${short(withSub)} tend to go together, from people who tried it.`]
			: onSub ? [`New to ${short(sub!)}? The curve up top shows when people usually feel it. Give it that long before taking more.`]
			: view === 'effects' ? ['Tap an effect to see what it is, and what people had taken when they felt it.']
			: ['Hi, I’m Spunion! Tap a substance to see how it usually goes, or tap two to see how they mix.'];
		return [...own, ...SPUNION_TIPS];
	})();
	const goCombo = (a: string, b: string) => {
		setView('reports');
		setSub(a);
		setWithSub(b);
		clearReport();
		setOpenItem(null);
	};

	return (
		<OpenCtx.Provider value={{ open: setOpenItem, effectInfo, classOf: (n: string) => classMap.get(n) }}>
			<main className="rd" style={{ minHeight: '100vh', background: BG, color: C.text }}>
				<style>{CSS}</style>
				<div className="px-4 py-6 sm:px-8 sm:py-8" style={{ maxWidth: onReport ? 1320 : 1120, margin: '0 auto', transition: 'max-width .3s', position: 'relative', isolation: 'isolate' }}>
					<div aria-hidden className="rd-molecules" style={{ backgroundImage: MOLECULES }} />
					<div aria-hidden className="rd-molecules b" style={{ backgroundImage: MOLECULES, backgroundPosition: '90px 140px' }} />
					<header className="mb-10 flex flex-wrap items-center justify-between gap-4" style={{ position: 'relative', zIndex: 2 }}>
						<button
							onClick={() => {
								setView('reports');
								setSub(undefined as unknown as null);
								setWithSub(undefined as unknown as null);
								clearReport();
							}}
							aria-label="re:dose home"
						>
							<img src={LOGO} alt="re:dose" style={{ height: 34, width: 'auto', display: 'block' }} />
						</button>
						<nav className="flex items-center gap-1">
							{(['reports', 'substances', 'effects'] as const).map((v) => (
								<button key={v} className="rd-nav" aria-current={view === v ? 'page' : undefined} onClick={() => setView(v)}>
									{v[0].toUpperCase() + v.slice(1)}
								</button>
							))}
							<a className="rd-nav inline-flex items-center gap-2" href={REDOSE_DISCORD} target="_blank" rel="noopener noreferrer" title="Join the re:dose community on Discord" style={{ textDecoration: 'none' }}>
								<DiscordIcon size={15} />
								<span className="rd-hide-sm">Community</span>
							</a>
						</nav>
					</header>

					{view === 'reports' && (sub || reportId) && (
						<nav className="mb-6 flex items-center gap-2 text-sm" style={{ color: C.faint, position: 'relative', zIndex: 2 }}>
							<button onClick={() => (setSub(undefined as unknown as null), setWithSub(undefined as unknown as null), clearReport())} style={{ color: C.soft }}>
								All substances
							</button>
							{sub && (
								<>
									<ChevronRight size={14} />
									{reportId ? (
										<button onClick={clearReport} title={sub} style={{ color: C.soft, whiteSpace: 'nowrap' }}>
											{short(sub)}
										</button>
									) : (
										<span title={sub} style={{ color: C.text, fontWeight: 600, whiteSpace: 'nowrap' }}>{short(sub)}{withSub ? ` + ${short(withSub)}` : ''}</span>
									)}
								</>
							)}
						</nav>
					)}

					{view === 'reports' && !sub && <SubstancesBrowse q={pickQ} onPick={goSubstance} onCombo={goCombo} />}
					{onSub && <ReportsStep sub={sub!} withSub={withSub} only={only} setOnly={(v: boolean) => setOnly(v || (undefined as unknown as boolean))} onCombo={goCombo} pairQ={comboPairQ} pairTimingQ={pairTimingQ} pairMoodQ={pairMoodQ} pairSummaryQ={pairSummaryQ} pairEffectsQ={pairEffectsQ} pairSeqQ={pairSeqQ} q={listQ} kq={kpiQ} curveQ={curveQ} denQ={denQ} horizon={horizon} onOpen={(rid) => (setAtLink(undefined as unknown as null), setReportId(rid))} />}
					{onReport && <TimelapseStep id={reportId!} reportQ={reportQ} marksQ={marksQ} dosesQ={dosesQ} obsQ={obsQ} timingQ={timingQ} pairsQ={pairsQ} frozen={!!openItem} />}
					{view === 'substances' && <SubstancesBrowse q={pickQ} onPick={goSubstance} onCombo={goCombo} />}
					{view === 'effects' && <EffectsBrowse q={effectsQ} />}

					<footer className="mt-16 flex flex-wrap items-center justify-between gap-x-8 gap-y-4 border-t pt-6 text-sm" style={{ borderColor: C.line, color: C.soft }}>
						{/* Report pages credit their sources under the story, so the footer stays short there. */}
						{!onReport && (
							<div className="flex flex-wrap items-center gap-3">
								<span>With thanks to</span>
								{(Object.keys(SOURCES) as (keyof typeof SOURCES)[]).map((k) => (
									<a key={k} className="rd-logo" href={SOURCES[k].href} target="_blank" rel="noopener noreferrer" title={`${SOURCES[k].name}: ${SOURCES[k].gives}`} aria-label={SOURCES[k].name}>
										<img src={SOURCES[k].logo} alt="" width={18} height={18} />
									</a>
								))}
							</div>
						)}
						<div className="flex flex-wrap items-center gap-4">
							<span className="text-xs" style={{ color: C.faint }}>Not medical advice.</span>
							<a className="rd-btn inline-flex items-center gap-2" href={REDOSE_DISCORD} target="_blank" rel="noopener noreferrer" style={{ textDecoration: 'none', fontSize: 13, padding: '6px 12px' }}>
								<DiscordIcon size={15} />
								Join the community
							</a>
						</div>
					</footer>
				</div>
				<DetailPanel item={openItem} onClose={() => setOpenItem(null)} effectQ={effectDetailQ} subQ={subDetailQ} timingQ={subTimingQ} onReplay={goSubstance} />
				{!openItem && <Spunion tips={spunionTips} lift={onReport} />}
			</main>
		</OpenCtx.Provider>
	);
}
